const CustomSoundUploader: React.FC<{
  label: string;
  sound?: CustomSound;
  onUpload: (sound: CustomSound) => void;
  onReset: () => void;
}> = ({ label, sound, onUpload, onReset }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.size > 2 * 1024 * 1024) { // 2MB limit
      alert("File is too large. Please select a file smaller than 2MB.");
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const dataUrl = e.target?.result as string;
      onUpload({ name: file.name, dataUrl });
    };
    reader.onerror = () => {
      alert("Failed to read file.");
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="flex items-center justify-between">
      <span className="text-white">{label}</span>
      <div className="flex items-center gap-2">
        <span className="text-sm text-gray-400 truncate max-w-[100px]" title={sound?.name ?? 'Default'}>
          {sound?.name ?? 'Default'}
        </span>
        <input
          type="file"
          accept="audio/*"
          ref={fileInputRef}
          onChange={handleFileChange}
          className="hidden"
        />
        <button
          onClick={() => fileInputRef.current?.click()}
          className="px-3 py-1 text-sm bg-gray-600 hover:bg-gray-500 rounded-md"
        >
          Change
        </button>
        <button
          onClick={onReset}
          disabled={!sound}
          className="p-2 text-gray-400 hover:text-white disabled:opacity-50 disabled:cursor-not-allowed"
          title="Reset to default"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h5M20 20v-5h-5" />
            <path strokeLinecap="round" strokeLinejoin="round" d="M4 9a9 9 0 0114.13-5.23M20 15a9 9 0 01-14.13 5.23" />
          </svg>
        </button>
      </div>
    </div>
  );
};

export const SettingsMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void; }> = ({ isOpen, setIsOpen }) => {
  const { settings, updateSettings } = useSettings();
  const { getDebugReportAsString } = useLogger();
  const { user } = useAuth();
  const workoutContext = useWorkout();

  const [isPinned, setIsPinned] = useState(false);
  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const durationInputRef = useRef<HTMLInputElement>(null);
  const restInputRef = useRef<HTMLInputElement>(null);
  const preWorkoutInputRef = useRef<HTMLInputElement>(null);

  const [localCountdownDurationStr, setLocalCountdownDurationStr] = useState(settings.countdownDuration.toString());
  const [localRestDurationStr, setLocalRestDurationStr] = useState(settings.countdownRestDuration.toString());
  const [localPreWorkoutCountdownStr, setLocalPreWorkoutCountdownStr] = useState(settings.preWorkoutCountdownDuration.toString());
  const [copyStatus, setCopyStatus] = useState('Copy Debug Info');


  useEffect(() => {
    if (document.activeElement !== durationInputRef.current) {
      setLocalCountdownDurationStr(settings.countdownDuration.toString());
    }
  }, [settings.countdownDuration]);

  useEffect(() => {
    if (document.activeElement !== restInputRef.current) {
      setLocalRestDurationStr(settings.countdownRestDuration.toString());
    }
  }, [settings.countdownRestDuration]);

  useEffect(() => {
    if (document.activeElement !== preWorkoutInputRef.current) {
      setLocalPreWorkoutCountdownStr(settings.preWorkoutCountdownDuration.toString());
    }
  }, [settings.preWorkoutCountdownDuration]);

  // Auto-close logic
  useEffect(() => {
    if (!isOpen && closeTimerRef.current) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
    return () => {
      if (closeTimerRef.current) {
        clearTimeout(closeTimerRef.current);
      }
    };
  }, [isOpen]);

  // Effect to handle wheel events on number inputs without scrolling the parent
  useEffect(() => {
    const handleWheel = (
      e: WheelEvent,
      stateUpdater: React.Dispatch<React.SetStateAction<string>>,
      min: number
    ) => {
      e.preventDefault();
      const input = e.currentTarget as HTMLInputElement;
      if (document.activeElement === input) {
        input.blur();
      }
      const delta = e.deltaY > 0 ? -1 : 1;
      stateUpdater(prev => {
          const currentVal = parseInt(prev, 10) || 0;
          const nextVal = currentVal + delta;
          if (nextVal < min) return min.toString();
          return nextVal.toString();
      });
    };

    const durationEl = durationInputRef.current;
    const restEl = restInputRef.current;
    const preWorkoutEl = preWorkoutInputRef.current;

    const durationWheelHandler = (e: WheelEvent) => handleWheel(e, setLocalCountdownDurationStr, 1);
    const restWheelHandler = (e: WheelEvent) => handleWheel(e, setLocalRestDurationStr, 0);
    const preWorkoutWheelHandler = (e: WheelEvent) => handleWheel(e, setLocalPreWorkoutCountdownStr, 1);

    if (durationEl) durationEl.addEventListener('wheel', durationWheelHandler, { passive: false });
    if (restEl) restEl.addEventListener('wheel', restWheelHandler, { passive: false });
    if (preWorkoutEl) preWorkoutEl.addEventListener('wheel', preWorkoutWheelHandler, { passive: false });

    return () => {
      if (durationEl) durationEl.removeEventListener('wheel', durationWheelHandler);
      if (restEl) restEl.removeEventListener('wheel', restWheelHandler);
      if (preWorkoutEl) preWorkoutEl.removeEventListener('wheel', preWorkoutWheelHandler);
    };
  }, []);

  const handleMouseEnter = () => {
    if (closeTimerRef.current) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  };

  const handleDurationBlur = () => {
     const num = parseInt(localCountdownDurationStr, 10);
     const finalValue = !isNaN(num) && num >= 1 ? num : 1;
     setLocalCountdownDurationStr(finalValue.toString());
     updateSettings({ countdownDuration: finalValue });
  };

  const handleRestBlur = () => {
     const num = parseInt(localRestDurationStr, 10);
     const finalValue = !isNaN(num) && num >= 0 ? num : 0;
     setLocalRestDurationStr(finalValue.toString());
     updateSettings({ countdownRestDuration: finalValue });
  };

  const handlePreWorkoutBlur = () => {
     const num = parseInt(localPreWorkoutCountdownStr, 10);
     const finalValue = !isNaN(num) && num >= 1 ? num : 1;
     setLocalPreWorkoutCountdownStr(finalValue.toString());
     updateSettings({ preWorkoutCountdownDuration: finalValue });
  };


  const handleClose = () => {
    handleDurationBlur();
    handleRestBlur();
    handlePreWorkoutBlur();
    setIsOpen(false);
    setIsPinned(false);
  };

  const handleMouseLeave = () => {
    if (isOpen && !isPinned) {
      closeTimerRef.current = setTimeout(() => {
        handleClose();
      }, 10000);
    }
  };

  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const handleTouchStart = (e: React.TouchEvent) => {
    touchEndX.current = null;
    touchStartX.current = e.touches[0].clientX;
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.touches[0].clientX;
  };

  const handleTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const distance = touchEndX.current - touchStartX.current;
    if (distance > minSwipeDistance) {
        handleClose();
    }
    touchStartX.current = null;
    touchEndX.current = null;
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newVolume = parseFloat(e.target.value);
    updateSettings({ volume: newVolume, isMuted: newVolume === 0 });
  };

  const toggleMute = () => {
    if (settings.isMuted) {
      updateSettings({
        isMuted: false,
        volume: settings.volume === 0 ? 0.5 : settings.volume,
      });
    } else {
      updateSettings({ isMuted: true });
    }
  };

  const playVolumeFeedback = () => {
    if (settings.allSoundsEnabled && !settings.isMuted && !settings.stealthModeEnabled) {
      playNotificationSound(settings.volume);
    }
  };

  const handleCopyDebugInfo = () => {
    const reportString = getDebugReportAsString({ settings, user, workoutContext });
    navigator.clipboard.writeText(reportString).then(() => {
        setCopyStatus('Copied!');
        setTimeout(() => setCopyStatus('Copy Debug Info'), 2000);
    }).catch(err => {
        console.error('Failed to copy debug info:', err);
        setCopyStatus('Copy Failed!');
        setTimeout(() => setCopyStatus('Copy Debug Info'), 2000);
    });
  };

  // --- Drag and drop state and logic ---
  const [draggedInfo, setDraggedInfo] = useState<{
    index: number;
    id: string;
    mouseOffsetY: number;
    elementHeight: number;
    elementWidth: number;
    elementX: number;
  } | null>(null);
  const [currentY, setCurrentY] = useState<number | null>(null);
  const [overIndex, setOverIndex] = useState<number | null>(null);
  const categoryRefs = useRef<(HTMLDivElement | null)[]>([]);

  const handleMouseDown = (e: React.MouseEvent<HTMLHeadingElement>, index: number, key: string) => {
    if (e.button !== 0) return; // Only left-click
    e.preventDefault();

    const target = e.currentTarget.parentElement?.parentElement;
    if (!target) return;

    const rect = target.getBoundingClientRect();

    setDraggedInfo({
      index,
      id: key,
      mouseOffsetY: e.clientY - rect.top,
      elementHeight: rect.height,
      elementWidth: rect.width,
      elementX: rect.left,
    });
    setCurrentY(e.clientY);
    setOverIndex(index);
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!draggedInfo) return;
      setCurrentY(e.clientY);

      let newOverIndex = draggedInfo.index;
      let closestDistance = Infinity;

      categoryRefs.current.forEach((ref, index) => {
          if (ref) {
              const rect = ref.getBoundingClientRect();
              const midY = rect.top + rect.height / 2;
              const distance = Math.abs(e.clientY - midY);

              if (distance < closestDistance) {
                  closestDistance = distance;
                  newOverIndex = index;
              }
          }
      });

      if (newOverIndex !== overIndex) {
          setOverIndex(newOverIndex);
      }
    };

    const handleMouseUp = () => {
      if (!draggedInfo || overIndex === null) {
        setDraggedInfo(null);
        return;
      };

      if (draggedInfo.index !== overIndex) {
        const newOrder = [...settings.settingsCategoryOrder];
        const [draggedItem] = newOrder.splice(draggedInfo.index, 1);
        newOrder.splice(overIndex, 0, draggedItem);
        updateSettings({ settingsCategoryOrder: newOrder });
      }

      setDraggedInfo(null);
    };

    if (draggedInfo) {
      document.body.style.cursor = 'grabbing';
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }

    return () => {
      document.body.style.cursor = '';
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [draggedInfo, overIndex, settings.settingsCategoryOrder, updateSettings]);

  const handleResetSound = (soundType: 'start' | 'end' | 'notification' | 'tick') => {
    const newSounds = { ...settings.customSounds };
    delete newSounds[soundType];
    updateSettings({ customSounds: newSounds });
  };

  const categories: Record<string, { title: string, content: React.ReactNode }> = {
    sounds: {
      title: "Sounds",
      content: (
          <div className="bg-gray-700/50 p-3 rounded-lg space-y-4">
            <div className="flex items-center gap-3">
              <button 
                onClick={toggleMute} 
                aria-label={settings.isMuted ? 'Unmute' : 'Mute'}
                className="text-white p-1 focus:outline-none rounded-full disabled:opacity-50"
                disabled={!settings.allSoundsEnabled}
              >
                  {settings.isMuted || settings.volume === 0 ? (
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15zM17 14l-4-4m0 4l4-4" /></svg>
                  ) : (
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                  )}
              </button>
                <input
                  type="range"
                  id="volumeControl"
                  min="0"
                  max="1"
                  step="0.01"
                  value={settings.isMuted ? 0 : settings.volume}
                  onChange={handleVolumeChange}
                  onMouseUp={playVolumeFeedback}
                  onKeyUp={playVolumeFeedback}
                  className="w-full h-2 bg-gray-600 rounded-lg appearance-none cursor-pointer disabled:opacity-50"
                  disabled={!settings.allSoundsEnabled}
                />
            </div>
            <hr className="border-gray-600" />
            <Toggle id="allSoundsEnabled" label="Enable All Sounds" checked={settings.allSoundsEnabled} onChange={(e) => updateSettings({ allSoundsEnabled: e.target.checked })} />
            <Toggle id="playSoundAtHalfway" label="Play at halfway" checked={settings.playSoundAtHalfway} onChange={(e) => updateSettings({ playSoundAtHalfway: e.target.checked })} disabled={!settings.allSoundsEnabled} />
            <Toggle id="playSoundAtEnd" label="Play at end" checked={settings.playSoundAtEnd} onChange={(e) => updateSettings({ playSoundAtEnd: e.target.checked })} disabled={!settings.allSoundsEnabled} />
            <Toggle id="playSoundOnRestart" label="Play on restart" checked={settings.playSoundOnRestart} onChange={(e) => updateSettings({ playSoundOnRestart: e.target.checked })} disabled={!settings.allSoundsEnabled} />
          </div>
      )
    },
    customSounds: {
      title: "Custom Sounds",
      content: (
        <div className="bg-gray-700/50 p-3 rounded-lg space-y-4">
          <p className="text-xs text-gray-400">Upload audio files (mp3, wav, etc. under 2MB) for workout events.</p>
          <CustomSoundUploader
            label="Start/Restart"
            sound={settings.customSounds?.start}
            onUpload={(sound) => updateSettings({ customSounds: { ...settings.customSounds, start: sound } })}
            onReset={() => handleResetSound('start')}
          />
          <CustomSoundUploader
            label="Halfway"
            sound={settings.customSounds?.notification}
            onUpload={(sound) => updateSettings({ customSounds: { ...settings.customSounds, notification: sound } })}
            onReset={() => handleResetSound('notification')}
          />
          <CustomSoundUploader
            label="Last 3 Seconds"
            sound={settings.customSounds?.tick}
            onUpload={(sound) => updateSettings({ customSounds: { ...settings.customSounds, tick: sound } })}
            onReset={() => handleResetSound('tick')}
          />
          <CustomSoundUploader
            label="End of Interval"
            sound={settings.customSounds?.end}
            onUpload={(sound) => updateSettings({ customSounds: { ...settings.customSounds, end: sound } })}
            onReset={() => handleResetSound('end')}
          />
        </div>
      )
    },
    countdown: {
      title: "Countdown",
      content: (
        <div className="bg-gray-700/50 p-3 rounded-lg space-y-4">
          <div className="flex items-center justify-between">
              <label htmlFor="countdownDuration" className="text-white">Duration (s)</label>
              <input ref={durationInputRef} type="number" id="countdownDuration" min="1" autoComplete="off" className="w-20 bg-gray-600 text-white text-center rounded-md p-1 focus:ring-2 focus:outline-none ring-blue-500 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none" value={localCountdownDurationStr} onChange={(e) => setLocalCountdownDurationStr(e.target.value)} onBlur={handleDurationBlur} />
          </div>
          <div className="flex items-center justify-between">
            <label htmlFor="countdownRestDuration" className="text-white">Rest Duration (s)</label>
            <input ref={restInputRef} type="number" id="countdownRestDuration" min="0" autoComplete="off" className="w-20 bg-gray-600 text-white text-center rounded-md p-1 focus:ring-2 focus:outline-none ring-blue-500 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none" value={localRestDurationStr} onChange={(e) => setLocalRestDurationStr(e.target.value)} onBlur={handleRestBlur} />
          </div>
          <div className="flex items-center justify-between">
              <label htmlFor="preWorkoutDuration" className="text-white">Pre-Workout Time (s)</label>
              <input ref={preWorkoutInputRef} type="number" id="preWorkoutDuration" min="1" autoComplete="off" className="w-20 bg-gray-600 text-white text-center rounded-md p-1 focus:ring-2 focus:outline-none ring-blue-500 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none" value={localPreWorkoutCountdownStr} onChange={(e) => setLocalPreWorkoutCountdownStr(e.target.value)} onBlur={handlePreWorkoutBlur} />
          </div>
          <hr className="border-gray-600" />
          <Toggle id="showCountdownToggle" label="Show Countdown" checked={settings.showCountdown} onChange={(e) => updateSettings({ showCountdown: e.target.checked })} />
          <Toggle id="showCountdownControlsToggle" label="Show Controls" checked={settings.showCountdownControls} onChange={(e) => updateSettings({ showCountdownControls: e.target.checked })} />
          <Toggle id="showRestTitleToggle" label="Show 'Rest' Title" checked={settings.showRestTitleOnDefaultCountdown} onChange={(e) => updateSettings({ showRestTitleOnDefaultCountdown: e.target.checked })} />
          <Toggle id="keepScreenOnToggle" label="Keep Screen On" checked={settings.keepScreenOnEnabled} onChange={(e) => updateSettings({ keepScreenOnEnabled: e.target.checked })} />
        </div>
      )
    },
    stopwatch: {
      title: "Stopwatch",
      content: (
        <div className="bg-gray-700/50 p-3 rounded-lg space-y-4">
          <Toggle id="showTimerToggle" label="Show Stopwatch" checked={settings.showTimer} onChange={(e) => updateSettings({ showTimer: e.target.checked })} />
          <Toggle id="showStopwatchControlsToggle" label="Show Controls" checked={settings.showStopwatchControls} onChange={(e) => updateSettings({ showStopwatchControls: e.target.checked })} />
          <Toggle id="showCycleCounterToggle" label="Show Cycle Counter" checked={settings.showCycleCounter} onChange={(e) => updateSettings({ showCycleCounter: e.target.checked })} />
          <Toggle id="showLogSessionButtonToggle" label="Show Log Button" checked={settings.showLogSessionButton} onChange={(e) => updateSettings({ showLogSessionButton: e.target.checked })} />
        </div>
      )
    },
    workoutDisplay: {
      title: "Workout Display",
      content: (
        <div className="bg-gray-700/50 p-3 rounded-lg space-y-4">
          <Toggle id="showNextExercise" label="Show Next Exercise" checked={settings.showNextExercise} onChange={(e) => updateSettings({ showNextExercise: e.target.checked })} />
        </div>
      )
    },
    displaySizes: {
      title: "Display Sizes",
      content: (
        <div className="bg-gray-700/50 p-3 rounded-lg space-y-4">
          <RangeSlider id="countdownSize" label="Countdown" value={settings.countdownSize} onChange={e => updateSettings({ countdownSize: parseInt(e.target.value, 10) })} />
          <RangeSlider id="stopwatchSize" label="Stopwatch" value={settings.stopwatchSize} onChange={e => updateSettings({ stopwatchSize: parseInt(e.target.value, 10) })} />
          <RangeSlider id="countdownControlsSize" label="Countdown Controls" value={settings.countdownControlsSize} onChange={e => updateSettings({ countdownControlsSize: parseInt(e.target.value, 10) })} />
          <RangeSlider id="stopwatchControlsSize" label="Stopwatch Controls" value={settings.stopwatchControlsSize} onChange={e => updateSettings({ stopwatchControlsSize: parseInt(e.target.value, 10) })} />
        </div>
      )
    },
    displayColors: {
      title: "Display Colors",
      content: (
        <div className="bg-gray-700/50 p-3 rounded-lg space-y-4">
          <div className="flex items-center justify-between">
            <label htmlFor="backgroundColor" className="text-white">Background</label>
            <input type="color" id="backgroundColor" value={settings.backgroundColor} onChange={(e) => updateSettings({ backgroundColor: e.target.value })} className="w-10 h-10 p-0 bg-transparent border-none rounded-md cursor-pointer" title="Set the main background color" />
          </div>
          <div className="flex items-center justify-between">
            <label htmlFor="halfwayColor" className="text-white">Halfway Background</label>
            <input type="color" id="halfwayColor" value={settings.halfwayColor} onChange={(e) => updateSettings({ halfwayColor: e.target.value })} className="w-10 h-10 p-0 bg-transparent border-none rounded-md cursor-pointer" title="Set background color for second half of countdown" />
          </div>
          <div className="flex items-center justify-between">
            <label htmlFor="restBackgroundColor" className="text-white">Rest Background</label>
            <input type="color" id="restBackgroundColor" value={settings.restBackgroundColor} onChange={(e) => updateSettings({ restBackgroundColor: e.target.value })} className="w-10 h-10 p-0 bg-transparent border-none rounded-md cursor-pointer" title="Set background color for rest periods" />
          </div>
        </div>
      )
    },
    developer: {
      title: "Developer",
      content: (
        <div className="bg-gray-700/50 p-3 rounded-lg space-y-4">
          <p className="text-sm text-gray-400">If you encounter a bug, copy this information and send it to the developer for assistance.</p>
          <button
            onClick={handleCopyDebugInfo}
            className="w-full text-center py-2 bg-blue-600 text-white rounded-lg font-semibold hover:bg-blue-700 transition-colors"
          >
            {copyStatus}
          </button>
        </div>
      )
    }
  };

  const ghostElement = useMemo(() => {
      if (!draggedInfo || currentY === null) return null;
      const category = categories[draggedInfo.id];
      if (!category) return null;
      const top = currentY - draggedInfo.mouseOffsetY;

      return (
          <div 
            style={{
              position: 'fixed',
              pointerEvents: 'none',
              zIndex: 100,
              left: draggedInfo.elementX,
              top: top,
              width: draggedInfo.elementWidth,
              boxShadow: '0 10px 20px rgba(0,0,0,0.2)',
              transform: 'scale(1.02)',
              background: 'rgb(31 41 55)', // solid gray-800
              borderRadius: '0.5rem',
            }}
          >
            <div>
              <h3 className="text-lg font-semibold text-gray-300 mb-3 cursor-grabbing px-3 pt-3">
                {category.title}
              </h3>
              {category.content}
            </div>
          </div>
      )
  }, [draggedInfo, currentY, categories]);


  const currentOrder = settings.settingsCategoryOrder || Object.keys(categories);
  categoryRefs.current = [];

  return (
    <>
      {ghostElement}
      <div className="absolute top-4 right-4 menu-container group">
        <button 
          onClick={() => isOpen ? handleClose() : setIsOpen(true)} 
          aria-label="Open settings menu"
          className="w-12 h-12 flex items-center justify-center rounded-full bg-gray-500/20 text-gray-400 hover:bg-gray-500/30 transition-opacity duration-1000 focus:outline-none opacity-0 group-hover:opacity-100"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
        </button>
      </div>

      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40"
          onClick={() => !isPinned && handleClose()}
        ></div>
      )}

      <div 
        className={`fixed top-0 right-0 h-full w-full max-w-sm bg-gray-800/80 backdrop-blur-md shadow-2xl z-50 transform transition-all ease-in-out ${isOpen ? 'duration-500' : 'duration-[1500ms]'} ${isOpen ? 'translate-x-0 opacity-100' : 'translate-x-full opacity-0 pointer-events-none'}`}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
      >
        <div className="p-6 overflow-y-auto h-full">
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-2xl font-bold text-white">Settings</h2>
            <div className="flex items-center gap-2">
              <button 
                onClick={() => setIsPinned(!isPinned)}
                className={`p-2 rounded-full hover:bg-gray-500/30 ${isPinned ? 'text-blue-400' : 'text-gray-400'}`}
                title={isPinned ? 'Unpin Menu' : 'Pin Menu'}
              >
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 3a1 1 0 01.707.293l3 3a1 1 0 01-1.414 1.414L10 5.414 7.707 7.707a1 1 0 01-1.414-1.414l3-3A1 1 0 0110 3zm-3.707 9.293a1 1 0 011.414 0L10 14.586l2.293-2.293a1 1 0 011.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" transform="rotate(45 10 10)" /></svg>
              </button>
              <button onClick={handleClose} aria-label="Close settings menu" className="p-2 rounded-full hover:bg-gray-500/30">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
          </div>

          <div className="space-y-8">
            {currentOrder.map((key, index) => {
              const category = categories[key];
              if (!category) return null;

              const isBeingDragged = draggedInfo?.index === index;

              let transform = 'translateY(0px)';
              if (draggedInfo && overIndex !== null && draggedInfo.index !== overIndex) {
                  const draggedHeight = draggedInfo.elementHeight + 32; // 32 is space-y-8 (2rem)
                  if (draggedInfo.index < overIndex) { // Dragging down
                      if (index > draggedInfo.index && index <= overIndex) {
                          transform = `translateY(-${draggedHeight}px)`;
                      }
                  } else { // Dragging up
                      if (index < draggedInfo.index && index >= overIndex) {
                          transform = `translateY(${draggedHeight}px)`;
                      }
                  }
              }

              return (
                <div
                  key={key}
                  ref={el => { if(el) categoryRefs.current[index] = el; }}
                  className="transition-transform duration-300 ease-in-out"
                  style={{ transform }}
                >
                  <div style={{ visibility: isBeingDragged ? 'hidden' : 'visible' }}>
                    <h3
                      className="text-lg font-semibold text-gray-300 mb-3 cursor-grab"
                      onMouseDown={(e) => handleMouseDown(e, index, key)}
                    >
                      {category.title}
                    </h3>
                    {category.content}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </>
  );
};

import React, { createContext, useContext, useState, useEffect, useCallback, ReactNode, useMemo, useRef } from 'react';
import { WorkoutPlan, WorkoutStep, WorkoutLogEntry, StepStatus, PerformedStep } from '../types';
import { prefetchExercises } from '../services/geminiService';
import { getBaseExerciseName, generateCircuitSteps, processAndFormatAiSteps, arePlansDeeplyEqual, migratePlanToV2 } from '../utils/workout';
import { useSettings } from './SettingsContext';
import { getLocalPlans, saveLocalPlans, getLocalHistory, saveLocalHistory } from '../services/storageService';
import { useAuth } from './AuthContext';
import { db } from '../services/firebase';
import { collection, doc, writeBatch, query, orderBy, setDoc, deleteDoc, onSnapshot, Unsubscribe, getDocs, FirestoreError } from 'firebase/firestore';
import { useLogger } from './LoggingContext';

const ACK_FINGERPRINT_KEY = 'acknowledgedGuestDataFingerprint';

const getGuestDataFingerprint = (plans: WorkoutPlan[], history: WorkoutLogEntry[]): string => {
    const planIds = plans.map(p => p.id).sort().join(',');
    const historyIds = history.map(h => h.id).sort().join(',');
    return `${planIds}|${historyIds}`;
};

export interface ActiveWorkout {
  plan: WorkoutPlan; // This can be a "meta-plan" if multiple plans are selected
  currentStepIndex: number;
  sourcePlanIds: string[];
  stepRestartKey?: number;
  // For detailed logging
  sessionLog: PerformedStep[];
  stepStartTime: number; // performance.now() timestamp
}

interface ImportNotificationData {
    message: string;
    planName: string;
    type: 'success' | 'warning';
}

export interface GuestMergeOptions {
    mergePlans: boolean;
    plansToMerge: WorkoutPlan[];
    mergeHistory: boolean;
}

interface WorkoutContextType {
  plans: WorkoutPlan[];
  activeWorkout: ActiveWorkout | null;
  currentStep: WorkoutStep | null;
  nextUpcomingStep: WorkoutStep | null;
  isWorkoutPaused: boolean;
  isCountdownPaused: boolean;
  recentlyImportedPlanId: string | null;
  workoutHistory: WorkoutLogEntry[];
  isPreparingWorkout: boolean;
  isSyncing: boolean;
  importNotification: ImportNotificationData | null;
  showGuestMergeModal: boolean;
  guestPlansToMerge: WorkoutPlan[];
  guestHistoryToMerge: WorkoutLogEntry[];
  handleMergeGuestData: (options: GuestMergeOptions) => void;
  handleDiscardGuestData: () => void;
  clearImportNotification: () => void;
  savePlan: (plan: WorkoutPlan) => void;
  importPlan: (plan: WorkoutPlan, source?: string) => void;
  deletePlan: (planId: string) => void;
  reorderPlans: (reorderedPlans: WorkoutPlan[]) => void;
  startWorkout: (planIds: string[]) => void;
  commitStartWorkout: () => void;
  clearPreparingWorkout: () => void;
  stopWorkout: (options: { completed: boolean; durationMs: number; finishedWorkout: ActiveWorkout }) => void;
  nextStep: (timestamp: number, status: StepStatus) => void;
  previousStep: (timestamp: number) => void;
  pauseWorkout: () => void;
  resumeWorkout: () => void;
  restartWorkout: () => void;
  pauseStepCountdown: () => void;
  resumeStepCountdown: () => void;
  restartCurrentStep: () => void;
  clearWorkoutHistory: () => void;
  forceSync: () => void;
  logManualSession: (name: string, durationMs: number, performedSteps: PerformedStep[]) => void;
}

const WorkoutContext = createContext<WorkoutContextType | undefined>(undefined);

export const WorkoutProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { settings } = useSettings();
  const { user, authStatus } = useAuth();
  const { logAction } = useLogger();
  const [plans, setPlans] = useState<WorkoutPlan[]>([]);
  const [activeWorkout, setActiveWorkout] = useState<ActiveWorkout | null>(null);
  const [isWorkoutPaused, setIsWorkoutPaused] = useState(false);
  const [isCountdownPaused, setIsCountdownPaused] = useState(false);
  const [recentlyImportedPlanId, setRecentlyImportedPlanId] = useState<string | null>(null);
  const [workoutHistory, setWorkoutHistory] = useState<WorkoutLogEntry[]>([]);
  const [plansToStart, setPlansToStart] = useState<string[]>([]);
  const [importNotification, setImportNotification] = useState<ImportNotificationData | null>(null);
  const [isSyncing, setIsSyncing] = useState(true);

  const [showGuestMergeModal, setShowGuestMergeModal] = useState(false);
  const [guestPlansToMerge, setGuestPlansToMerge] = useState<WorkoutPlan[]>([]);
  const [guestHistoryToMerge, setGuestHistoryToMerge] = useState<WorkoutLogEntry[]>([]);
  const initialSyncDone = useRef(false);

  // Ref to hold the current auth status to use in callbacks without adding it as a dependency.
  const authStatusRef = useRef(authStatus);
  useEffect(() => {
    authStatusRef.current = authStatus;
  }, [authStatus]);


  const isPreparingWorkout = plansToStart.length > 0;

  const clearImportNotification = useCallback(() => setImportNotification(null), []);

  const handleFirestoreError = useCallback((error: FirestoreError, context: string) => {
      console.error(`Firestore error in ${context}:`, error);
      logAction(`ERROR_FIRESTORE_${context}`, { message: error.message, code: error.code });

      if (error.code === 'permission-denied') {
          setImportNotification({
              message: 'שגיאת הרשאות',
              planName: 'נא לעדכן חוקי אבטחה ב-Firebase Console',
              type: 'warning',
          });
      }
      setIsSyncing(false);
  }, [logAction]);

  useEffect(() => {
    let plansUnsubscribe: Unsubscribe | undefined;
    let historyUnsubscribe: Unsubscribe | undefined;

    const cleanup = () => {
        if (plansUnsubscribe) plansUnsubscribe();
        if (historyUnsubscribe) historyUnsubscribe();
        initialSyncDone.current = false;
        setShowGuestMergeModal(false);
        setGuestPlansToMerge([]);
        setGuestHistoryToMerge([]);
    };

    if (authStatus === 'authenticated' && user) {
        logAction('AUTH_STATE_AUTHENTICATED', { uid: user.uid });
        setIsSyncing(true);
        initialSyncDone.current = false;

        let remotePlansCache: WorkoutPlan[] = [];
        let remoteHistoryCache: WorkoutLogEntry[] = [];
        let plansListenerDone = false;
        let historyListenerDone = false;

        const checkAndTriggerMergeModal = () => {
            if (!plansListenerDone || !historyListenerDone || initialSyncDone.current) return;

            initialSyncDone.current = true;

            const localPlans = getLocalPlans().map(migratePlanToV2).filter((p): p is WorkoutPlan => !!p);
            const remotePlanIds = new Set(remotePlansCache.map(p => p.id));
            const newGuestPlans = localPlans.filter(p => !remotePlanIds.has(p.id));

            const localHistory = getLocalHistory();
            const remoteHistoryIds = new Set(remoteHistoryCache.map(h => h.id));
            const newGuestHistory = localHistory.filter(h => !remoteHistoryIds.has(h.id));

            const guestDataFingerprint = getGuestDataFingerprint(newGuestPlans, newGuestHistory);
            const acknowledgedFingerprint = localStorage.getItem(ACK_FINGERPRINT_KEY);

            if (guestDataFingerprint === acknowledgedFingerprint) {
                 logAction('GUEST_DATA_ACKNOWLEDGED');
                 return;
            }

            if (newGuestPlans.length > 0 || newGuestHistory.length > 0) {
                logAction('GUEST_DATA_DETECTED', { planCount: newGuestPlans.length, historyCount: newGuestHistory.length });
                setGuestPlansToMerge(newGuestPlans);
                setGuestHistoryToMerge(newGuestHistory);
                setShowGuestMergeModal(true);
            } else {
                logAction('GUEST_DATA_NONE_DETECTED');
            }
        };

        const plansCollection = collection(db, 'users', user.uid, 'plans');
        plansUnsubscribe = onSnapshot(query(plansCollection, orderBy('order', 'asc')), (snapshot) => {
            remotePlansCache = snapshot.docs.map(doc => migratePlanToV2(doc.data())).filter((p): p is WorkoutPlan => !!p);
            setPlans(remotePlansCache);

            if (!plansListenerDone) {
                plansListenerDone = true;
                checkAndTriggerMergeModal();
            }
            setIsSyncing(false);
        }, (error) => handleFirestoreError(error, 'PLANS_LISTENER'));

        const historyCollection = collection(db, 'users', user.uid, 'history');
        historyUnsubscribe = onSnapshot(query(historyCollection, orderBy('date', 'desc')), (snapshot) => {
            remoteHistoryCache = snapshot.docs.map(doc => doc.data() as WorkoutLogEntry);

            // Robustly merge remote data with local-only fallback data
            const remoteHistoryIds = new Set(remoteHistoryCache.map(h => h.id));
            const localHistory = getLocalHistory();
            const localOnlyHistory = localHistory.filter(h => !remoteHistoryIds.has(h.id));
            const combinedHistory = [...remoteHistoryCache, ...localOnlyHistory].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
            setWorkoutHistory(combinedHistory);

            if (!historyListenerDone) {
                historyListenerDone = true;
                checkAndTriggerMergeModal();
            }
        }, (error) => handleFirestoreError(error, 'HISTORY_LISTENER'));

    } else if (authStatus === 'unauthenticated') {
        logAction('AUTH_STATE_UNAUTHENTICATED');
        cleanup(); // Detaches any previous Firestore listeners.

        // This is now the single source of truth for loading guest data.
        setPlans(getLocalPlans().map(migratePlanToV2).filter((p): p is WorkoutPlan => !!p));
        setWorkoutHistory(getLocalHistory());

        // On sign out, clear all active session state regardless.
        setActiveWorkout(null);
        setIsWorkoutPaused(false);
        setIsCountdownPaused(false);
        setPlansToStart([]);

        setIsSyncing(false);
    }

    return cleanup;
  }, [user, authStatus, logAction, handleFirestoreError]);


  const forceSync = useCallback(async () => {
    if (!user) return;
    logAction('SYNC_FORCE_ATTEMPT');
    setIsSyncing(true);
    try {
        const plansCollection = collection(db, 'users', user.uid, 'plans');
        const remoteSnapshot = await getDocs(query(plansCollection, orderBy('order', 'asc')));
        const remotePlans = remoteSnapshot.docs.map(doc => migratePlanToV2(doc.data())).filter((p): p is WorkoutPlan => !!p);
        setPlans(remotePlans);
        logAction('SYNC_FORCE_SUCCESS', { planCount: remotePlans.length });
    } catch (error) {
        logAction('ERROR_SYNC_FORCE', { message: (error as Error).message });
        console.error("Manual sync failed:", error);
        if ((error as FirestoreError).code === 'permission-denied') {
             setImportNotification({
                  message: 'שגיאת הרשאות',
                  planName: 'נא לעדכן חוקי אבטחה ב-Firebase',
                  type: 'warning',
             });
        }
    } finally {
        setIsSyncing(false);
    }
  }, [user, logAction]);

  const handleDiscardGuestData = useCallback(() => {
    logAction('GUEST_DATA_DISCARDED');
    const fingerprint = getGuestDataFingerprint(guestPlansToMerge, guestHistoryToMerge);
    localStorage.setItem(ACK_FINGERPRINT_KEY, fingerprint);
    setShowGuestMergeModal(false);
    setGuestPlansToMerge([]);
    setGuestHistoryToMerge([]);
  }, [logAction, guestPlansToMerge, guestHistoryToMerge]);

  const handleMergeGuestData = useCallback(async (options: GuestMergeOptions) => {
    logAction('GUEST_DATA_MERGE_ATTEMPT', options);
    const { mergePlans, plansToMerge, mergeHistory } = options;

    if (!user) {
        setShowGuestMergeModal(false);
        return;
    };

    if (!mergePlans && !mergeHistory) {
        handleDiscardGuestData();
        return;
    }

    setIsSyncing(true);
    setShowGuestMergeModal(false);

    try {
        const batch = writeBatch(db);

        let plansToUpload: WorkoutPlan[] = [];
        if (mergePlans && plansToMerge.length > 0) {
            const maxOrder = plans.reduce((max, p) => Math.max(max, p.order ?? -1), -1);
            plansToUpload = plansToMerge.map((p, i) => ({ ...p, order: maxOrder + 1 + i }));

            plansToUpload.forEach((plan) => {
                const planRef = doc(db, 'users', user.uid, 'plans', plan.id);
                batch.set(planRef, plan);
            });
        }

        if (mergeHistory && guestHistoryToMerge.length > 0) {
            guestHistoryToMerge.forEach(entry => {
                const historyRef = doc(db, 'users', user.uid, 'history', entry.id);
                batch.set(historyRef, entry);
            });
        }

        await batch.commit();
        logAction('GUEST_DATA_MERGE_SUCCESS');

        const fingerprint = getGuestDataFingerprint(guestPlansToMerge, guestHistoryToMerge);
        localStorage.setItem(ACK_FINGERPRINT_KEY, fingerprint);

        if (mergePlans && plansToUpload.length > 0) {
            saveLocalPlans([...plans, ...plansToUpload]);
        }
        if (mergeHistory && guestHistoryToMerge.length > 0) {
            saveLocalHistory([...workoutHistory, ...guestHistoryToMerge]);
        }

    } catch (error) {
        logAction('ERROR_GUEST_DATA_MERGE', { message: (error as Error).message });
        console.error("Failed to merge guest data:", error);
        if ((error as FirestoreError).code === 'permission-denied') {
             setImportNotification({
                  message: 'שגיאת הרשאות במיזוג',
                  planName: 'בדוק את חוקי Firebase',
                  type: 'warning',
             });
        }
        setShowGuestMergeModal(true); 
    } finally {
        setGuestPlansToMerge([]);
        setGuestHistoryToMerge([]);
        setIsSyncing(false);
    }
  }, [user, plans, guestHistoryToMerge, guestPlansToMerge, workoutHistory, handleDiscardGuestData, logAction]);

  const savePlan = useCallback(async (planToSave: WorkoutPlan) => {
      logAction('PLAN_SAVE_ATTEMPT', { planId: planToSave.id, planName: planToSave.name });
      const migratedPlan = migratePlanToV2(planToSave);
      if (!migratedPlan) {
          logAction('ERROR_PLAN_SAVE_MIGRATION_FAILED', { planId: planToSave.id });
          return;
      }

      setPlans(prevPlans => {
          const isNewPlan = !prevPlans.some(p => p.id === migratedPlan.id);
          const plansWithOrder = prevPlans.map((p, i) => ({ ...p, order: i }));
          let newPlans;

          if (isNewPlan) {
              const maxOrder = plansWithOrder.reduce((max, p) => Math.max(max, p.order ?? -1), -1);
              migratedPlan.order = maxOrder + 1;
              newPlans = [...plansWithOrder, migratedPlan];
          } else {
              newPlans = plansWithOrder.map(p => p.id === migratedPlan.id ? migratedPlan : p);
          }

          // Always save locally as immediate cache/backup
          saveLocalPlans(newPlans);

          return newPlans;
      });

      if (user) {
          try {
              const planRef = doc(db, 'users', user.uid, 'plans', migratedPlan.id);
              await setDoc(planRef, migratedPlan, { merge: true });
          } catch (error) {
              logAction('ERROR_PLAN_SAVE_FIRESTORE', { planId: migratedPlan.id, message: (error as Error).message });
              console.error("Failed to save plan to Firestore:", error);
              if ((error as FirestoreError).code === 'permission-denied') {
                 setImportNotification({
                      message: 'שמירה נכשלה',
                      planName: 'אין הרשאת כתיבה למסד הנתונים',
                      type: 'warning',
                 });
              }
          }
      }
  }, [user, logAction]);

  const importPlan = useCallback((planToImport: WorkoutPlan, source: string = 'file') => {
    logAction('PLAN_IMPORT_ATTEMPT', { planName: planToImport.name, source });
    const migratedPlan = migratePlanToV2(planToImport);
    if (!migratedPlan) {
        logAction('ERROR_PLAN_IMPORT_MIGRATION_FAILED', { planName: planToImport.name });
        setImportNotification({ message: "Import failed", planName: "The plan data was invalid.", type: 'warning' });
        return;
    }

    const isDuplicate = plans.some(existingPlan => arePlansDeeplyEqual(migratedPlan, existingPlan));

    if (isDuplicate) {
        logAction('PLAN_IMPORT_DUPLICATE', { planName: migratedPlan.name });
        setImportNotification({
            message: 'האימון כבר קיים',
            planName: `"${migratedPlan.name}" לא יובא שוב.`,
            type: 'warning',
        });
        return;
    }

    const newPlanId = `${Date.now()}_imported_from_${source}`;
    const newPlan: WorkoutPlan = {
      ...migratedPlan,
      id: newPlanId,
      name: migratedPlan.name,
      steps: migratedPlan.steps.map((step, index) => ({
        ...step,
        id: `${Date.now()}_imported_step_${index}`
      }))
    };

    if (source === 'ai') {
        newPlan.steps = processAndFormatAiSteps(newPlan.steps);
        // FIX: Sanitize AI-generated steps to prevent invalid states like time-based exercises with 0 duration.
        newPlan.steps = newPlan.steps.map(step => {
            if (step.type === 'exercise' && !step.isRepBased && (!step.duration || step.duration <= 0)) {
                // This is an invalid time-based step. Convert it to a rep-based step as a fallback.
                return {
                    ...step,
                    isRepBased: true,
                    reps: 10, // A sensible default for reps.
                    duration: 0,
                };
            }
            return step;
        });
    }

    savePlan(newPlan);

    setImportNotification({
        message: 'תוכנית אימונים יובאה בהצלחה!',
        planName: newPlan.name,
        type: 'success',
    });

    const exerciseNames = newPlan.steps
        .filter(s => s.type === 'exercise')
        .map(s => s.name);
    prefetchExercises(exerciseNames);

    setRecentlyImportedPlanId(newPlanId);
    setTimeout(() => setRecentlyImportedPlanId(null), 2500);
  }, [savePlan, plans, logAction]);

  useEffect(() => {
    const handleImportFromUrl = () => {
        const hash = window.location.hash;
        if (hash.startsWith('#import=')) {
            logAction('URL_IMPORT_DETECTED');
            try {
                const base64Data = hash.substring(8);
                const binaryString = atob(base64Data);
                const bytes = new Uint8Array(binaryString.length);
                for (let i = 0; i < binaryString.length; i++) {
                    bytes[i] = binaryString.charCodeAt(i);
                }
                const decoder = new TextDecoder('utf-8');
                const jsonString = decoder.decode(bytes);
                const plan = JSON.parse(jsonString);

                if (plan && typeof plan.name === 'string' && Array.isArray(plan.steps)) {
                    importPlan(plan, 'url');
                } else {
                    throw new Error("Invalid plan structure in URL.");
                }
            } catch (e) {
                logAction('ERROR_URL_IMPORT', { message: (e as Error).message });
                console.error("Failed to import from URL", e);
                alert("Could not import workout plan from the link. The link may be invalid or corrupted.");
            } finally {
                window.history.replaceState(null, '', window.location.pathname + window.location.search);
            }
        }
    };
    handleImportFromUrl();
  }, [importPlan, logAction]);


  const deletePlan = useCallback(async (planId: string) => {
    logAction('PLAN_DELETE_ATTEMPT', { planId });

    if (user) {
        try {
            const planRef = doc(db, 'users', user.uid, 'plans', planId);
            await deleteDoc(planRef);
            // On success, the onSnapshot listener will update the UI.
        } catch (error) {
            logAction('ERROR_PLAN_DELETE_FIRESTORE', { planId, message: (error as Error).message });
            console.error("Failed to delete plan from Firestore:", error);
            // On failure, inform the user clearly.
            setImportNotification({
                message: 'מחיקה נכשלה',
                planName: 'אין לך הרשאות למחוק תוכנית זו.',
                type: 'warning',
            });
        }
    } else { // Handle guest user (local storage only)
        const newPlans = plans.filter(p => p.id !== planId);
        setPlans(newPlans);
        saveLocalPlans(newPlans);
    }
  }, [user, plans, logAction]);

  const reorderPlans = useCallback(async (reorderedPlans: WorkoutPlan[]) => {
      logAction('PLANS_REORDERED', { count: reorderedPlans.length });
      const plansWithOrder = reorderedPlans.map((p, i) => ({ ...p, order: i }));
      setPlans(plansWithOrder);

      // Always save locally
      saveLocalPlans(plansWithOrder);

      if (user) {
        try {
            const batch = writeBatch(db);
            plansWithOrder.forEach((plan) => {
                const planRef = doc(db, 'users', user.uid, 'plans', plan.id);
                batch.set(planRef, plan, { merge: true });
            });
            await batch.commit();
        } catch (error) {
            logAction('ERROR_PLANS_REORDER_FIRESTORE', { message: (error as Error).message });
            console.error("Failed to reorder plans in Firestore:", error);
            if ((error as FirestoreError).code === 'permission-denied') {
                 setImportNotification({
                      message: 'שגיאת הרשאות',
                      planName: 'לא ניתן לשמור סדר חדש',
                      type: 'warning',
                 });
            }
        }
      }
  }, [user, logAction]);

  const logWorkoutCompletion = useCallback(async (
    planName: string, 
    durationMs: number, 
    steps: WorkoutStep[], 
    planIds: string[],
    performedSteps: PerformedStep[]
  ) => {
    const now = new Date();
    const newEntry: WorkoutLogEntry = {
        id: now.toISOString(),
        date: now.toISOString(),
        planName: planName,
        durationSeconds: Math.round(durationMs / 1000),
        steps: steps,
        planIds: planIds,
        performedSteps: performedSteps,
    };
    logAction('WORKOUT_LOGGED', { planName, duration: newEntry.durationSeconds, performedStepCount: performedSteps.length });

    const sanitizedEntry = JSON.parse(JSON.stringify(newEntry));

    const saveLocally = () => {
        setWorkoutHistory(prev => {
            const newHistory = [newEntry, ...prev];
            saveLocalHistory(newHistory);
            return newHistory;
        });
    };

    if (user) {
        try {
            const historyRef = doc(db, 'users', user.uid, 'history', newEntry.id);
            await setDoc(historyRef, sanitizedEntry);
        } catch (e) {
            logAction('ERROR_LOG_SAVE_FIRESTORE', { message: (e as Error).message });
            console.error("Failed to save workout log to Firestore:", e);
             if ((e as FirestoreError).code === 'permission-denied') {
                 setImportNotification({
                      message: 'היומן לא נשמר בענן',
                      planName: 'נשמר מקומית עקב בעיית הרשאות',
                      type: 'warning',
                 });
            }
            // Fallback to local storage if Firestore fails
            saveLocally();
        }
    } else {
        saveLocally();
    }
  }, [user, logAction]);

  const logManualSession = useCallback(async (name: string, durationMs: number, performedSteps: PerformedStep[]) => {
    const now = new Date();
    const newEntry: WorkoutLogEntry = {
        id: now.toISOString(),
        date: now.toISOString(),
        planName: name,
        durationSeconds: Math.round(durationMs / 1000),
        steps: performedSteps.map(p => p.step),
        planIds: ['manual_session'],
        performedSteps: performedSteps,
    };
    logAction('MANUAL_WORKOUT_LOGGED', { planName: name, duration: newEntry.durationSeconds, performedStepCount: performedSteps.length });

    const sanitizedEntry = JSON.parse(JSON.stringify(newEntry));

    const saveLocally = () => {
        setWorkoutHistory(prev => {
            const newHistory = [newEntry, ...prev];
            saveLocalHistory(newHistory);
            return newHistory;
        });
    };

    if (user) {
        try {
            const historyRef = doc(db, 'users', user.uid, 'history', newEntry.id);
            await setDoc(historyRef, sanitizedEntry);
        } catch (e) {
            logAction('ERROR_LOG_SAVE_FIRESTORE', { message: (e as Error).message });
            console.error("Failed to save manual workout log to Firestore:", e);
            if ((e as FirestoreError).code === 'permission-denied') {
                 setImportNotification({
                      message: 'היומן לא נשמר בענן',
                      planName: 'נשמר מקומית עקב בעיית הרשאות',
                      type: 'warning',
                 });
            }
            // Fallback to local storage if Firestore fails
            saveLocally();
        }
    } else {
        saveLocally();
    }
  }, [user, logAction]);

  const clearWorkoutHistory = useCallback(() => {
    if (window.confirm("Are you sure you want to delete your entire workout history? This action cannot be undone.")) {
        logAction('HISTORY_CLEAR_ATTEMPT');
        const performClear = async () => {
            if (user) {
                setIsSyncing(true);
                try {
                    const historyCollection = collection(db, 'users', user.uid, 'history');
                    const snapshot = await getDocs(historyCollection);
                    if (snapshot.empty) return;

                    const batch = writeBatch(db);
                    snapshot.forEach(doc => batch.delete(doc.ref));
                    await batch.commit();
                    logAction('HISTORY_CLEAR_SUCCESS_FIRESTORE');
                } catch (error) {
                    logAction('ERROR_HISTORY_CLEAR_FIRESTORE', { message: (error as Error).message });
                    console.error("Failed to clear Firestore history:", error);
                    if ((error as FirestoreError).code === 'permission-denied') {
                         setImportNotification({
                              message: 'מחיקה נכשלה',
                              planName: 'חסרות הרשאות מחיקה',
                              type: 'warning',
                         });
                    }
                } finally {
                    setIsSyncing(false);
                }
            } else {
                setWorkoutHistory([]);
                saveLocalHistory([]);
                logAction('HISTORY_CLEAR_SUCCESS_LOCAL');
            }
        };
        performClear();
    }
  }, [user, logAction]);

  const startWorkout = useCallback((planIds: string[]) => {
    logAction('WORKOUT_PREPARE', { planIds });
    if (planIds.length === 0) return;
    setPlansToStart(planIds);
  }, [logAction]);

  const clearPreparingWorkout = useCallback(() => {
    logAction('WORKOUT_PREPARE_CLEARED');
    setPlansToStart([]);
  }, [logAction]);

  const commitStartWorkout = useCallback(() => {
    if (plansToStart.length === 0) return;

    logAction('WORKOUT_START_COMMIT', { plansToStart });
    const plansToRun = plansToStart.map(id => plans.find(p => p.id === id)).filter(Boolean) as WorkoutPlan[];
    if (plansToRun.length === 0) {
        setPlansToStart([]);
        return;
    }

    const executionMode = plansToRun.length === 1 ? (plansToRun[0].executionMode || 'linear') : 'linear';
    let mainWorkoutSteps = plansToRun.flatMap(p => p.steps);

    if (executionMode === 'circuit') {
      mainWorkoutSteps = generateCircuitSteps(mainWorkoutSteps);
    }

    let allSteps: WorkoutStep[] = [];

    if (settings.isWarmupEnabled && settings.warmupSteps.length > 0) {
        const enabledWarmupSteps = settings.warmupSteps.filter(step => step.enabled !== false);
        const markedWarmupSteps = enabledWarmupSteps.map(step => ({ ...step, isWarmup: true }));
        allSteps.push(...markedWarmupSteps);

        if (settings.restAfterWarmupDuration > 0 && markedWarmupSteps.length > 0) {
            allSteps.push({
                id: `rest_after_warmup_${Date.now()}`,
                name: 'מנוחה לפני אימון',
                type: 'rest',
                isRepBased: false,
                duration: settings.restAfterWarmupDuration,
                reps: 0,
                isWarmup: true,
            });
        }
    }

    allSteps.push(...mainWorkoutSteps);

    if (allSteps.length === 0) {
        setPlansToStart([]);
        return;
    };

    const metaPlan: WorkoutPlan = {
      id: `meta_${Date.now()}`,
      name: plansToRun.map(p => p.name).join(' & '),
      steps: allSteps,
      executionMode: executionMode,
      version: 2,
    };

    const newActiveWorkout: ActiveWorkout = { 
      plan: metaPlan, 
      currentStepIndex: 0, 
      sourcePlanIds: plansToStart, 
      stepRestartKey: 0,
      sessionLog: [],
      stepStartTime: Date.now(),
    };

    setActiveWorkout(newActiveWorkout);
    logAction('WORKOUT_STARTED', { planName: newActiveWorkout.plan.name, stepCount: newActiveWorkout.plan.steps.length });

    setIsWorkoutPaused(false);
    setIsCountdownPaused(false);
    setPlansToStart([]);
  }, [plans, plansToStart, settings, logAction]);

  const stopWorkout = useCallback(({ completed, durationMs, finishedWorkout }: { completed: boolean; durationMs: number; finishedWorkout: ActiveWorkout }) => {
    logAction('WORKOUT_STOPPED', { completed, durationMs, planName: finishedWorkout.plan.name });
    if (completed) {
        const finalSessionLog = [...finishedWorkout.sessionLog];
        const lastStep = finishedWorkout.plan.steps[finishedWorkout.currentStepIndex];
        if (lastStep) {
            const stepDuration = Date.now() - finishedWorkout.stepStartTime;
            finalSessionLog.push({ step: lastStep, status: StepStatus.Completed, durationMs: stepDuration });
        }

        logWorkoutCompletion(
            finishedWorkout.plan.name || 'Unnamed Workout',
            durationMs,
            finishedWorkout.plan.steps,
            finishedWorkout.sourcePlanIds,
            finalSessionLog
        );
    }
    setActiveWorkout(null);
    setIsWorkoutPaused(false);
    setIsCountdownPaused(false);
  }, [logWorkoutCompletion, logAction]);

  const pauseWorkout = useCallback(() => {
      logAction('WORKOUT_PAUSED_GLOBAL');
      setIsWorkoutPaused(true);
  }, [logAction]);

  const resumeWorkout = useCallback(() => {
      logAction('WORKOUT_RESUMED_GLOBAL');
      setIsWorkoutPaused(false);
  }, [logAction]);

  const restartWorkout = useCallback(() => {
    logAction('WORKOUT_RESTARTED');
    setActiveWorkout(prev => prev ? { 
        ...prev, 
        currentStepIndex: 0, 
        stepRestartKey: (prev.stepRestartKey || 0) + 1,
        sessionLog: [],
        stepStartTime: Date.now(),
    } : null);
    setIsWorkoutPaused(false);
    setIsCountdownPaused(false);
  }, [logAction]);

  const nextStep = useCallback((timestamp: number, status: StepStatus) => {
    setActiveWorkout(prev => {
      if (!prev) return null;
      logAction('WORKOUT_NEXT_STEP', { currentIndex: prev.currentStepIndex, nextIndex: prev.currentStepIndex + 1, status });

      const currentStep = prev.plan.steps[prev.currentStepIndex];
      const durationMs = timestamp - prev.stepStartTime;
      const performedStep: PerformedStep = {
        step: currentStep,
        status,
        durationMs,
      };

      const newSessionLog = [...prev.sessionLog, performedStep];

      if (prev.currentStepIndex + 1 >= prev.plan.steps.length) {
        return null; 
      }

      return { 
        ...prev, 
        currentStepIndex: prev.currentStepIndex + 1,
        sessionLog: newSessionLog,
        stepStartTime: timestamp,
      };
    });
    setIsCountdownPaused(false);
  }, [logAction]);

  const previousStep = useCallback((timestamp: number) => {
    setActiveWorkout(prev => {
      if (!prev || prev.currentStepIndex === 0) return prev;
      logAction('WORKOUT_PREVIOUS_STEP', { currentIndex: prev.currentStepIndex, prevIndex: prev.currentStepIndex - 1 });

      const newSessionLog = prev.sessionLog.slice(0, -1);
      const lastPerformedStepDuration = newSessionLog.length > 0 ? newSessionLog[newSessionLog.length - 1].durationMs : 0;

      return { 
          ...prev, 
          currentStepIndex: prev.currentStepIndex - 1,
          sessionLog: newSessionLog,
          stepStartTime: timestamp - lastPerformedStepDuration
      };
    });
    setIsCountdownPaused(false);
  }, [logAction]);

  const pauseStepCountdown = useCallback(() => {
      logAction('WORKOUT_PAUSED_STEP_COUNTDOWN');
      setIsCountdownPaused(true);
  }, [logAction]);

  const resumeStepCountdown = useCallback(() => {
      logAction('WORKOUT_RESUMED_STEP_COUNTDOWN');
      setIsCountdownPaused(false);
  }, [logAction]);

  const restartCurrentStep = useCallback(() => {
    logAction('WORKOUT_RESTARTED_STEP');
    setActiveWorkout(prev => prev ? { 
        ...prev, 
        stepRestartKey: (prev.stepRestartKey || 0) + 1,
        stepStartTime: Date.now(),
    } : null);
    setIsCountdownPaused(false);
  }, [logAction]);

  const currentStep = activeWorkout ? activeWorkout.plan.steps[activeWorkout.currentStepIndex] : null;

  const nextUpcomingStep = useMemo(() => {
    if (!activeWorkout) return null;
    const { plan, currentStepIndex } = activeWorkout;
    for (let i = currentStepIndex + 1; i < plan.steps.length; i++) {
        if (plan.steps[i].type === 'exercise') return plan.steps[i];
    }
    return null;
  }, [activeWorkout]);


  const value = {
    plans,
    activeWorkout,
    currentStep,
    nextUpcomingStep,
    isWorkoutPaused,
    isCountdownPaused,
    recentlyImportedPlanId,
    workoutHistory,
    isPreparingWorkout,
    isSyncing,
    importNotification,
    showGuestMergeModal,
    guestPlansToMerge,
    guestHistoryToMerge,
    handleMergeGuestData,
    handleDiscardGuestData,
    clearImportNotification,
    savePlan,
    importPlan,
    deletePlan,
    reorderPlans,
    startWorkout,
    commitStartWorkout,
    clearPreparingWorkout,
    stopWorkout,
    nextStep,
    previousStep,
    pauseWorkout,
    resumeWorkout,
    restartWorkout,
    pauseStepCountdown,
    resumeStepCountdown,
    restartCurrentStep,
    clearWorkoutHistory,
    forceSync,
    logManualSession,
  };

  return <WorkoutContext.Provider value={value}>{children}</WorkoutContext.Provider>;
};

export const useWorkout = (): WorkoutContextType => {
  const context = useContext(WorkoutContext);
  if (context === undefined) {
    throw new Error('useWorkout must be used within a WorkoutProvider');
  }
  return context;
};

import React, { useState, useEffect, useRef, useMemo, useLayoutEffect } from 'react';
import { useWorkout } from '../contexts/WorkoutContext';
import { WorkoutPlan, WorkoutStep } from '../types';
import { useSettings } from '../contexts/SettingsContext';
import { HoverNumberInput } from './HoverNumberInput';
import { getExerciseInfo, ExerciseInfo, prefetchExercises, generateWorkoutPlan } from '../services/geminiService';
import { WorkoutInfoModal } from './WorkoutInfoModal';
import { WorkoutLog } from './WorkoutLog';
import { getBaseExerciseName, generateCircuitSteps, getStepDisplayName } from '../utils/workout';
import { useAuth } from '../contexts/AuthContext';

const EDITOR_STORAGE_KEY = 'sportsClockPlanEditorDraft';

const ExerciseInfoModal: React.FC<{
  exerciseName: string | null;
  onClose: () => void;
  isVisible: boolean;
}> = ({ exerciseName, onClose, isVisible }) => {
  const [info, setInfo] = useState<ExerciseInfo | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'howto' | 'details'>('howto');
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const modalRef = useRef<HTMLDivElement>(null);
  const [activeVideoId, setActiveVideoId] = useState<string | null>(null);
  const [showLoadingMessage, setShowLoadingMessage] = useState(false);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);


  useEffect(() => {
    const fetchInfo = async () => {
      if (!exerciseName) return;
      setIsLoading(true);
      setError(null);
      try {
        const result = await getExerciseInfo(exerciseName);
        setInfo(result);
        setActiveVideoId(result.primaryVideoId);
        if (result.instructions.toLowerCase().includes("error") || result.instructions.toLowerCase().includes("failed") || result.instructions.includes("api key") || result.instructions.includes("מפתח api") || result.instructions.includes("שגיאה") || result.instructions.includes("מכסת שימוש")) {
            setError(result.instructions);
        }
      } catch (e) {
        const errorMessage = e instanceof Error ? e.message : "Failed to fetch or parse exercise information.";
        setError(errorMessage);
        console.error(e);
      } finally {
        setIsLoading(false);
      }
    };
    if (isVisible && exerciseName) {
        fetchInfo();
    }
  }, [exerciseName, isVisible]);

  // Bug Fix: Clear video URL when modal is hidden to stop playback
  useEffect(() => {
    if (isVisible && activeVideoId) {
      setVideoUrl(`https://www.youtube.com/embed/${activeVideoId}?autoplay=1`);
    } else {
      setVideoUrl(null);
    }
  }, [isVisible, activeVideoId]);

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (isLoading && isVisible) {
        // Only show the long loading message if loading takes more than 500ms
        timer = setTimeout(() => {
            setShowLoadingMessage(true);
        }, 500);
    } else {
        setShowLoadingMessage(false);
    }
    return () => clearTimeout(timer);
  }, [isLoading, isVisible]);

  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    e.preventDefault();
    const startX = e.clientX - position.x;
    const startY = e.clientY - position.y;

    const handleMouseMove = (moveEvent: MouseEvent) => {
        setPosition({
            x: moveEvent.clientX - startX,
            y: moveEvent.clientY - startY,
        });
    };

    const handleMouseUp = () => {
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  const handleTouchStart = (e: React.TouchEvent<HTMLDivElement>) => {
    // e.preventDefault() might be too aggressive, let's see. It can prevent scrolling.
    const touch = e.touches[0];
    const startX = touch.clientX - position.x;
    const startY = touch.clientY - position.y;

    const handleTouchMove = (moveEvent: TouchEvent) => {
        const moveTouch = moveEvent.touches[0];
        setPosition({
            x: moveTouch.clientX - startX,
            y: moveTouch.clientY - startY,
        });
    };

    const handleTouchEnd = () => {
        document.removeEventListener('touchmove', handleTouchMove as any);
        document.removeEventListener('touchend', handleTouchEnd as any);
    };

    document.addEventListener('touchmove', handleTouchMove as any, { passive: false });
    document.addEventListener('touchend', handleTouchEnd as any);
  };

  const allVideoIds = useMemo(() => {
    if (!info) return [];
    const ids = [info.primaryVideoId, ...info.alternativeVideoIds].filter((id): id is string => !!id);
    return [...new Set(ids)]; // Remove duplicates
  }, [info]);

  const activeVideoIndex = useMemo(() => {
    if (!activeVideoId) return -1;
    return allVideoIds.indexOf(activeVideoId);
  }, [allVideoIds, activeVideoId]);

  const handleNextVideo = () => {
    if (allVideoIds.length === 0) return;
    const nextIndex = (activeVideoIndex + 1) % allVideoIds.length;
    setActiveVideoId(allVideoIds[nextIndex]);
  };

  const handlePrevVideo = () => {
    if (allVideoIds.length === 0) return;
    const prevIndex = (activeVideoIndex - 1 + allVideoIds.length) % allVideoIds.length;
    setActiveVideoId(allVideoIds[prevIndex]);
  };

  const isHebrew = useMemo(() => info?.language === 'he', [info]);

  const parsedInstructions = useMemo(() => {
    if (!info?.instructions) return [];

    const instructionsText = info.instructions.trim();
    let lines: string[];

    // First, try splitting by newline characters, which is the preferred format.
    if (instructionsText.includes('\n')) {
        lines = instructionsText.split('\n');
    } else {
        // Fallback: If no newlines, split by a pattern like "1. ", "2. ", etc.
        // The positive lookahead `(?=...)` splits *before* the number, keeping it for the next step.
        lines = instructionsText.split(/(?=\d+\.\s*)/);
    }

    return lines
      .map(line => line.trim().replace(/^\d+\.\s*/, '')) // remove the "1. " part
      .filter(line => line.length > 0);
  }, [info?.instructions]);

  const parsedTips = useMemo(() => {
    if (!info?.tips) return [];
    // This regex strips any leading number and dot (e.g., "1. ") to prevent "• 1. Tip" when rendered in a <ul>.
    return info.tips.map(tip => tip.trim().replace(/^\d+\.?\s*/, ''));
  }, [info?.tips]);

  const TabButton: React.FC<{
    label: string;
    isActive: boolean;
    onMouseDown: () => void;
