const AiProfilePanel: React.FC<{ isOpen: boolean; onClose: () => void; }> = ({ isOpen, onClose }) => {
    const { settings, updateSettings } = useSettings();
    const [newEquipment, setNewEquipment] = useState('');
    const { userProfile } = settings;

    const age = useMemo(() => {
        if (!userProfile?.birthDate) return null;
        try {
            const birthDate = new Date(userProfile.birthDate);
            const today = new Date();
            let age = today.getFullYear() - birthDate.getFullYear();
            const m = today.getMonth() - birthDate.getMonth();
            if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
                age--;
            }
            return age > 0 ? age : null;
        } catch {
            return null;
        }
    }, [userProfile?.birthDate]);

    const handleProfileUpdate = (field: keyof NonNullable<typeof userProfile>, value: any) => {
        updateSettings({
            userProfile: {
                ...userProfile,
                [field]: value,
            },
        });
    };

    const handleAddEquipment = () => {
        const trimmedName = newEquipment.trim();
        if (trimmedName === '') return;
        const currentEquipment = userProfile?.equipment || [];
        if (currentEquipment.some(e => e.name.toLowerCase() === trimmedName.toLowerCase())) return;

        handleProfileUpdate('equipment', [...currentEquipment, { name: trimmedName, available: true }]);
        setNewEquipment('');
    };

    const handleRemoveEquipment = (nameToRemove: string) => {
        handleProfileUpdate('equipment', (userProfile?.equipment || []).filter(e => e.name !== nameToRemove));
    };

    const handleToggleEquipment = (nameToToggle: string) => {
        handleProfileUpdate('equipment', (userProfile?.equipment || []).map(e => 
            e.name === nameToToggle ? { ...e, available: !e.available } : e
        ));
    };

    const FitnessButton: React.FC<{level: 'beginner' | 'intermediate' | 'advanced'}> = ({ level }) => {
        const isActive = userProfile?.fitnessLevel === level;
        return (
            <button 
                onClick={() => handleProfileUpdate('fitnessLevel', level)}
                className={`flex-1 py-2 text-sm font-semibold rounded-md transition-colors ${isActive ? 'bg-blue-600 text-white' : 'bg-gray-600 hover:bg-gray-500'}`}
            >
                {level.charAt(0).toUpperCase() + level.slice(1)}
            </button>
        );
    };

    return (
        <>
            <div 
                className={`fixed inset-0 bg-black/50 z-[101] transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`} 
                onClick={onClose}
            />
            <div 
                className={`fixed top-0 right-0 h-full w-full max-w-sm bg-gray-800 shadow-2xl z-[102] transform transition-transform duration-300 flex flex-col ${isOpen ? 'translate-x-0' : 'translate-x-full'}`}
                dir="rtl"
            >
                <div className="flex justify-between items-center p-4 border-b border-gray-700 shrink-0">
                    <h3 className="text-xl font-bold text-white">הפרופיל שלי</h3>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-gray-700">
                         <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>
                <div className="p-4 space-y-6 overflow-y-auto flex-grow">
                    <div>
                        <label className="text-sm font-semibold text-gray-300">תאריך לידה</label>
                        <div className="flex items-center gap-4 mt-1">
                            <input 
                                type="date"
                                value={userProfile?.birthDate || ''}
                                onChange={e => handleProfileUpdate('birthDate', e.target.value)}
                                className="bg-gray-700 p-2 rounded-md text-white w-full"
                            />
                            {age && <span className="text-lg font-bold text-white shrink-0">{age}</span>}
                        </div>
                    </div>
                    <div>
                        <label className="text-sm font-semibold text-gray-300">רמת כושר</label>
                        <div className="flex gap-2 mt-1">
                            <FitnessButton level="beginner" />
                            <FitnessButton level="intermediate" />
                            <FitnessButton level="advanced" />
                        </div>
                    </div>
                     <div>
                        <label className="text-sm font-semibold text-gray-300">הציוד שלי</label>
                        <div className="flex gap-2 mt-1">
                            <input 
                                type="text"
                                value={newEquipment}
                                onChange={e => setNewEquipment(e.target.value)}
                                onKeyPress={e => e.key === 'Enter' && handleAddEquipment()}
                                placeholder="הוסף ציוד..."
                                className="flex-grow bg-gray-700 p-2 rounded-md text-white"
                            />
                            <button onClick={handleAddEquipment} className="px-4 py-2 bg-blue-600 rounded-md font-semibold hover:bg-blue-700">+</button>
                        </div>
                        <div className="mt-3 space-y-2 max-h-60 overflow-y-auto pr-2">
                            {(userProfile?.equipment || []).map(item => (
                                <div key={item.name} className="flex items-center bg-gray-700/50 p-2 rounded-md">
                                    <input 
                                        type="checkbox"
                                        id={`equip-${item.name}`}
                                        checked={item.available}
                                        onChange={() => handleToggleEquipment(item.name)}
                                        className="w-5 h-5 bg-gray-600 border-gray-500 text-blue-500 rounded focus:ring-blue-500"
                                    />
                                    <label htmlFor={`equip-${item.name}`} className="flex-grow mx-3 text-white truncate cursor-pointer">{item.name}</label>
                                    <button onClick={() => handleRemoveEquipment(item.name)} className="p-1 text-gray-400 hover:text-red-500">
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
};


const AiPlannerModal: React.FC<{
    onClose: () => void;
}> = ({ onClose }) => {
    type ChatPart = { text: string; isPlanLink?: boolean; planName?: string };
    type ChatMessage = { role: 'user' | 'model'; parts: ChatPart[] };

    const { importPlan } = useWorkout();
    const { settings } = useSettings();
    const AI_CHAT_HISTORY_KEY = 'sportsClockAiChatHistory_v2';

    const [messages, setMessages] = useState<ChatMessage[]>(() => {
        try {
            const saved = localStorage.getItem(AI_CHAT_HISTORY_KEY);
            return saved ? JSON.parse(saved) : [];
        } catch { return []; }
    });
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isProfileOpen, setIsProfileOpen] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    useEffect(() => {
        localStorage.setItem(AI_CHAT_HISTORY_KEY, JSON.stringify(messages));
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [messages]);

    const adjustTextareaHeight = () => {
        const textarea = textareaRef.current;
        if (textarea) {
            textarea.style.height = 'auto';
            const scrollHeight = textarea.scrollHeight;

            const computedStyle = getComputedStyle(textarea);
            const lineHeight = parseFloat(computedStyle.lineHeight) || 24;
            const paddingTop = parseFloat(computedStyle.paddingTop);
            const paddingBottom = parseFloat(computedStyle.paddingBottom);
            const maxHeight = (lineHeight * 6) + paddingTop + paddingBottom;

            textarea.style.height = `${Math.min(scrollHeight, maxHeight)}px`;
            textarea.style.overflowY = scrollHeight > maxHeight ? 'auto' : 'hidden';
        }
    };

    useLayoutEffect(() => {
        adjustTextareaHeight();
    }, [input]);

    const handleNewChat = () => {
        setMessages([]);
        localStorage.removeItem(AI_CHAT_HISTORY_KEY);
    };

    const handleSend = async () => {
        if (!input.trim() || isLoading) return;

        const userMessage: ChatMessage = { role: 'user', parts: [{ text: input.trim() }] };
        const newMessages = [...messages, userMessage];
        setMessages(newMessages);
        setInput('');
        setIsLoading(true);

        let profileContext = '';
        if (settings.userProfile) {
            const { userProfile } = settings;
            const profileParts = [];
            if (userProfile.birthDate) {
                const birthDate = new Date(userProfile.birthDate);
                const age = new Date().getFullYear() - birthDate.getFullYear();
                if (age > 0 && age < 120) profileParts.push(`Age: ${age}`);
            }
            if (userProfile.fitnessLevel) {
                profileParts.push(`Fitness Level: ${userProfile.fitnessLevel}`);
            }
            const availableEquipment = userProfile.equipment?.filter(e => e.available).map(e => e.name);
            if (availableEquipment && availableEquipment.length > 0) {
                profileParts.push(`Available Equipment: ${availableEquipment.join(', ')}`);
            }
            if (profileParts.length > 0) {
                profileContext = profileParts.join('; ');
            }
        }

        try {
            const responseText = await generateWorkoutPlan(messages, input, profileContext);

            if (responseText.startsWith('Error: ')) {
                const userFriendlyMessage = responseText.substring('Error: '.length);
                setMessages(prev => [...prev, { role: 'model', parts: [{ text: userFriendlyMessage }] }]);
                return;
            }


            const jsonRegex = /```json\s*([\s\S]*?)\s*```/;
            const match = responseText.match(jsonRegex);
            const conversationalText = responseText.replace(jsonRegex, '').trim();

            let finalMessages = [...newMessages];

            if (conversationalText) {
                finalMessages.push({ role: 'model', parts: [{ text: conversationalText }]});
            }

            if (match && match[1]) {
                try {
                    const planJson = JSON.parse(match[1]);
                    planJson.isSmartPlan = true;
                    planJson.color = '#a855f7';

                    importPlan(planJson, 'ai');

                    finalMessages.push({ role: 'model', parts: [{ text: '', isPlanLink: true, planName: planJson.name }]});

                } catch (e) {
                    console.error("Failed to parse AI-generated JSON:", e);
                    finalMessages.push({ role: 'model', parts: [{ text: "I tried to generate a plan, but there was an error in the format. Could you please clarify your request? The full response is below for debugging:\n\n" + responseText }] });
                }
            } else if (!conversationalText) {
                 finalMessages.push({ role: 'model', parts: [{ text: responseText }]});
            }

            setMessages(finalMessages);

        } catch (error) {
            console.error("AI Planner error:", error);
            const errorMessage = error instanceof Error ? error.message : "Sorry, something went wrong.";
            setMessages([...newMessages, { role: 'model', parts: [{ text: errorMessage }] }]);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-gray-900/90 z-[100] flex flex-col p-4" aria-modal="true" role="dialog">
            <AiProfilePanel isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} />
             <div className="flex justify-between items-center mb-4 text-white">
                <button onClick={() => setIsProfileOpen(true)} title="הפרופיל שלי" className="p-2 rounded-full hover:bg-gray-700">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-6-3a2 2 0 11-4 0 2 2 0 014 0zm-2 4a5 5 0 00-4.546 2.916A5.986 5.986 0 0010 16a5.986 5.986 0 004.546-2.084A5 5 0 0010 11z" clipRule="evenodd" />
                    </svg>
                </button>
                <h2 className="text-xl font-bold flex items-center gap-2">✨ AI Workout Planner</h2>
                <div className="flex items-center gap-2">
                    <button onClick={handleNewChat} title="Start a new chat" className="p-2 rounded-full hover:bg-gray-700">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 110 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0v-2.101a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" /></svg>
                    </button>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-gray-700">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>
            </div>
            <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2">
                 {messages.length === 0 && (
                    <div className="text-center text-gray-400 p-8" dir="rtl">
                        <p className="text-lg">ברוכים הבאים למתכנן האימונים החכם!</p>
                        <p className="mt-2">תאר את האימון שברצונך לבנות. לדוגמה:</p>
                        <em className="block mt-2">"צור לי תוכנית אימון למתחילים באורך 20 דקות לכל הגוף."</em>
                    </div>
                )}
                {messages.map((msg, index) => (
                    <div key={index} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-prose p-3 rounded-lg ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-200'}`}>
                            {msg.parts.map((part, partIndex) => 
                                part.isPlanLink ? (
                                    <div key={partIndex} dir="auto">
                                        <p>הוספתי את תוכנית "{part.planName}" לרשימה שלך.</p>
                                        <button onClick={onClose} className="mt-2 font-bold text-blue-300 hover:text-blue-200 underline">
                                            הצג תוכנית
                                        </button>
                                    </div>
                                ) : (
                                    <p key={partIndex} className="whitespace-pre-wrap" dir="auto">{part.text}</p>
                                )
                            )}
                        </div>
                    </div>
                ))}
                {isLoading && (
                     <div className="flex justify-start">
                        <div className="max-w-sm p-3 rounded-lg bg-gray-700 text-gray-200">
                            <div className="flex items-center gap-3">
                                <div className="flex items-center gap-2">
                                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0s'}}></div>
                                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.1s'}}></div>
                                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
                                </div>
                                <span className="text-sm italic text-gray-400">בונה לך את האימון המושלם, כמה רגעים...</span>
                            </div>
                        </div>
                    </div>
                )}
                 <div ref={messagesEndRef} />
            </div>
            <div className="flex gap-2">
                <textarea
                    ref={textareaRef}
                    rows={1}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSend();
                        }
                    }}
                    placeholder="תאר את האימון הרצוי..."
                    className="flex-grow bg-gray-800 text-white p-3 rounded-lg focus:outline-none focus:ring-2 ring-blue-500 resize-none transition-[height] duration-200"
                    dir="rtl"
                    disabled={isLoading}
                />
                <button onClick={handleSend} disabled={isLoading || !input.trim()} className="px-6 py-3 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-700 disabled:bg-gray-600 disabled:cursor-not-allowed">
                    Send
                </button>
            </div>
        </div>
    );
};


export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void; }> = ({ isOpen, setIsOpen }) => {
  const [isPinned, setIsPinned] = useState(false);
  const [editingPlan, setEditingPlan] = useState<WorkoutPlan | null | string>(null);
  const [view, setView] = useState<'list' | 'editor' | 'log'>('list');
  const [confirmDeletePlanId, setConfirmDeletePlanId] = useState<string | null>(null);
  const [exerciseToInspect, setExerciseToInspect] = useState<string | null>(null);
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [infoPlan, setInfoPlan] = useState<WorkoutPlan | null>(null);
  const { activeWorkout, plans, deletePlan } = useWorkout();
  const { settings, updateSettings } = useSettings();
  const modalMutedApp = useRef(false);
  const [isAiPlannerOpen, setIsAiPlannerOpen] = useState(false);

  // Mute app sounds when the exercise modal is visible and restore on close.
  useEffect(() => {
    if (isModalVisible) {
      // Modal is opening.
      if (!settings.isMuted) {
        modalMutedApp.current = true;
        updateSettings({ isMuted: true });
      }
    } else {
      // Modal is closing.
      if (modalMutedApp.current) {
        modalMutedApp.current = false;
        updateSettings({ isMuted: false });
      }
    }
  }, [isModalVisible, settings.isMuted, updateSettings]);

  const planToDelete = useMemo(() => {
    return plans.find(p => p.id === confirmDeletePlanId) || null;
  }, [confirmDeletePlanId, plans]);

  const planToEdit = useMemo(() => {
    if(editingPlan === null) return null;
    if(typeof editingPlan === 'string' && editingPlan === '_warmup_') {
        return {
            id: '_warmup_',
            name: 'חימום',
            steps: settings.warmupSteps,
            color: '#f97316', // Orange for warm-up
            version: 2,
        } as WorkoutPlan
    }
    return editingPlan as WorkoutPlan;
  }, [editingPlan, settings.warmupSteps]);

  // Touch handlers for swipe-to-close gesture
  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const handleTouchStart = (e: React.TouchEvent) => {
      touchEndX.current = null;
      touchStartX.current = e.touches[0].clientX;
  };
  const handleTouchMove = (e: React.TouchEvent) => {
      touchEndX.current = e.touches[0].clientX;
  };
  const handleTouchEnd = () => {
      if (!touchStartX.current || !touchEndX.current) return;
      const distance = touchEndX.current - touchStartX.current;
      // Swipe left to close, respecting the pin
      if (distance < -minSwipeDistance && !isPinned) {
          setIsOpen(false);
      }
      touchStartX.current = null;
      touchEndX.current = null;
  };

  useEffect(() => {
    if (!isOpen) {
        setIsPinned(false); // Unpin when manually closed
        setTimeout(() => {
             setView('list');
             setEditingPlan(null);
        }, 500); 
    }
  }, [isOpen]);

  const handleCreateNew = () => {
      localStorage.removeItem(EDITOR_STORAGE_KEY);
      setEditingPlan(null);
      setView('editor');
  };

  const handleSelectPlan = (plan: WorkoutPlan | string) => {
      localStorage.removeItem(EDITOR_STORAGE_KEY);
      setEditingPlan(plan);
      setView('editor');
  };

  const handleBack = () => {
      setView('list');
      setEditingPlan(null);
  };

  const handleConfirmDelete = () => {
    if (confirmDeletePlanId) {
        deletePlan(confirmDeletePlanId);
        setConfirmDeletePlanId(null);
    }
  };

  const handleInspectExercise = (exerciseName: string) => {
    if (isModalVisible && exerciseToInspect === exerciseName) {
        return;
    }
    setExerciseToInspect(exerciseName);
    setIsModalVisible(true);
  };

  const handleCloseModal = () => {
    setIsModalVisible(false);
  };

  useEffect(() => {
      if(activeWorkout && !isPinned) {
          setIsOpen(false);
      }
  }, [activeWorkout, isPinned]);


  return (
    <>
      <div className="absolute top-4 left-4 menu-container group">
        <button 
          onClick={() => setIsOpen(!isOpen)} 
          aria-label="Open workout planner"
          className="w-12 h-12 flex items-center justify-center rounded-full bg-gray-500/20 text-gray-400 hover:bg-gray-500/30 transition-opacity duration-1000 focus:outline-none opacity-0 group-hover:opacity-100"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" /></svg>
        </button>
      </div>

      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40"
          onClick={() => !isPinned && setIsOpen(false)}
        ></div>
      )}

      {planToDelete && (
          <ConfirmDeleteModal 
              planName={planToDelete.name}
              onConfirm={handleConfirmDelete}
              onCancel={() => setConfirmDeletePlanId(null)}
          />
      )}

      <ExerciseInfoModal 
          exerciseName={exerciseToInspect}
          onClose={handleCloseModal}
          isVisible={isModalVisible}
      />

      {infoPlan && <WorkoutInfoModal plan={infoPlan} onClose={() => setInfoPlan(null)} />}

      {isAiPlannerOpen && <AiPlannerModal onClose={() => setIsAiPlannerOpen(false)} />}

      <div 
        className={`fixed top-0 left-0 h-full w-full max-w-sm bg-gray-800/80 backdrop-blur-md shadow-2xl z-50 transform transition-all ease-in-out ${isOpen ? 'duration-500' : 'duration-[1500ms]'} ${isOpen ? 'translate-x-0 opacity-100' : '-translate-x-full opacity-0 pointer-events-none'}`}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        >
          <div className="p-6 overflow-y-auto h-full">
            {view === 'list' && (
                <PlanList 
                    onSelectPlan={handleSelectPlan} 
                    onCreateNew={handleCreateNew} 
                    onInitiateDelete={setConfirmDeletePlanId}
                    onShowLog={() => setView('log')}
                    onInspectExercise={handleInspectExercise}
                    onShowInfo={setInfoPlan}
                    isPinned={isPinned}
                    onTogglePin={() => setIsPinned(!isPinned)}
                    onOpenAiPlanner={() => setIsAiPlannerOpen(true)}
                />
            )}
            {view === 'editor' && (
                <PlanEditor 
                    plan={planToEdit} 
                    onBack={handleBack} 
                    isWarmupEditor={typeof editingPlan === 'string' && editingPlan === '_warmup_'}
                />
            )}
            {view === 'log' && (
                <WorkoutLog onBack={handleBack} />
            )}
          </div>
        </div>
    </>
  );
};

import React, { useMemo, useEffect, useRef, useState, useCallback } from 'react';
import { CountdownDisplay } from './components/CountdownDisplay';
import { CountdownControls } from './components/CountdownControls';
import { TimerDisplay } from './components/TimerDisplay';
import { Controls } from './components/Controls';
import { SettingsMenu } from './components/SettingsMenu';
import { WorkoutMenu } from './components/WorkoutMenu';
import { RepDisplay } from './components/RepDisplay';
import { PreWorkoutCountdown } from './components/PreWorkoutCountdown';
import { GuestDataMergeModal } from './components/GuestDataMergeModal';
import { LogSessionModal } from './components/LogSessionModal';
import { useStopwatch } from './hooks/useStopwatch';
import { useCountdown } from './hooks/useCountdown';
import { SettingsProvider, useSettings } from './contexts/SettingsContext';
import { WorkoutProvider, useWorkout, ActiveWorkout } from './contexts/WorkoutContext';
import { playNotificationSound, resumeAudioContext } from './utils/sound';
import { getStepDisplayName } from './utils/workout';
import { ImportNotification } from './components/ImportNotification';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import { StepStatus, PerformedStep, WorkoutStep } from './types';
import { LoggingProvider, useLogger } from './contexts/LoggingContext';
import { ErrorBoundary } from './components/ErrorBoundary';
import { CrashNotification } from './components/CrashNotification';

const CRASH_FLAG_KEY = 'app_crash_detected';

const AppContent: React.FC = () => {
  const { settings, updateSettings } = useSettings();
  const { user } = useAuth();
  const workoutContext = useWorkout();
  const { 
    activeWorkout, 
    currentStep, 
    nextUpcomingStep,
    stopWorkout: contextStopWorkout,
    isWorkoutPaused,
    pauseWorkout,
    resumeWorkout,
    isCountdownPaused,
    pauseStepCountdown,
    resumeStepCountdown,
    restartCurrentStep,
    isPreparingWorkout,
    commitStartWorkout,
    clearPreparingWorkout,
    importNotification,
    clearImportNotification,
    showGuestMergeModal,
    guestPlansToMerge,
    guestHistoryToMerge,
    handleMergeGuestData,
    handleDiscardGuestData,
    logManualSession,
    nextStep,
    previousStep,
  } = workoutContext;

  const stopwatch = useStopwatch();
  const wasWorkoutActive = useRef(false);
  const lastActiveWorkoutRef = useRef<ActiveWorkout | null>(null);
  const [workoutCompleted, setWorkoutCompleted] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isWorkoutOpen, setIsWorkoutOpen] = useState(false);
  const [preWorkoutTimeLeft, setPreWorkoutTimeLeft] = useState<number | null>(null);
  const { logAction, getDebugReportAsString } = useLogger();
  const [showCrashNotification, setShowCrashNotification] = useState(false);

  const [manualSessionLog, setManualSessionLog] = useState<PerformedStep[]>([]);
  const [isLoggingModalOpen, setIsLoggingModalOpen] = useState(false);
  const prevCycleCount = useRef(0);

  // Check for crash flag on initial app load
  useEffect(() => {
    try {
        if (localStorage.getItem(CRASH_FLAG_KEY) === 'true') {
            setShowCrashNotification(true);
        }
    } catch (e) {
        console.error("Could not read crash flag from localStorage:", e);
    }
  }, []);

  // Screen Wake Lock implementation
  useEffect(() => {
    let wakeLock: any = null;
    const requestWakeLock = async () => {
        if ('wakeLock' in navigator && settings.keepScreenOnEnabled) {
            try {
                wakeLock = await (navigator as any).wakeLock.request('screen');
                logAction('WAKE_LOCK_ACQUIRED');
                wakeLock.addEventListener('release', () => {
                    logAction('WAKE_LOCK_RELEASED');
                });
            } catch (err: any) {
                console.error(`${err.name}, ${err.message}`);
                logAction('WAKE_LOCK_ERROR', { name: err.name, message: err.message });
            }
        }
    };

    requestWakeLock();

    // Re-request wake lock if tab becomes visible again
    const handleVisibilityChange = () => {
        if (wakeLock !== null && document.visibilityState === 'visible') {
            requestWakeLock();
        }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
        if (wakeLock) {
            wakeLock.release().then(() => {
                wakeLock = null;
            });
        }
        document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [settings.keepScreenOnEnabled, logAction]);

  const handleCopyCrashReport = useCallback(() => {
    const report = getDebugReportAsString({ settings, user, workoutContext });
    navigator.clipboard.writeText(report).then(() => {
        // Report copied to clipboard
    }).catch(err => {
        console.error("Failed to copy crash report:", err);
    });
    setShowCrashNotification(false);
    localStorage.removeItem(CRASH_FLAG_KEY);
  }, [getDebugReportAsString, settings, user, workoutContext]);

  const handleDismissCrashReport = useCallback(() => {
    setShowCrashNotification(false);
    localStorage.removeItem(CRASH_FLAG_KEY);
  }, []);

  // Resume AudioContext on first user interaction
  useEffect(() => {
    const handleFirstInteraction = () => {
      logAction('FIRST_USER_INTERACTION');
      resumeAudioContext();
      window.removeEventListener('click', handleFirstInteraction);
      window.removeEventListener('touchstart', handleFirstInteraction);
      window.removeEventListener('keydown', handleFirstInteraction);
    };

    window.addEventListener('click', handleFirstInteraction);
    window.addEventListener('touchstart', handleFirstInteraction);
    window.addEventListener('keydown', handleFirstInteraction);

    return () => {
      window.removeEventListener('click', handleFirstInteraction);
      window.removeEventListener('touchstart', handleFirstInteraction);
      window.removeEventListener('keydown', handleFirstInteraction);
    };
  }, [logAction]);

  const nextStepWithTime = useCallback((status: StepStatus) => {
      nextStep(Date.now(), status);
  }, [nextStep]);

  const previousStepWithTime = useCallback(() => {
    previousStep(Date.now());
  }, [previousStep]);


  const isWorkoutActive = !!(activeWorkout && currentStep);
  const isRepStep = isWorkoutActive && currentStep.isRepBased;
  const countdownDuration = isWorkoutActive && !isRepStep ? currentStep.duration : (isWorkoutActive && isRepStep ? 0 : settings.countdownDuration);
  const isRestStep = isWorkoutActive && currentStep.type === 'rest';

  const countdown = useCountdown(
    countdownDuration, 
    settings.countdownRestDuration, 
    settings,
    (isWorkoutActive && !isRepStep) ? () => nextStepWithTime(StepStatus.Completed) : undefined,
    isWorkoutActive ? `${currentStep.id}-${activeWorkout.currentStepIndex}-${activeWorkout.stepRestartKey || 0}` : undefined,
    isRestStep
  );

  // Track manual session cycles
  useEffect(() => {
    if (!isWorkoutActive && countdown.cycleCount > prevCycleCount.current) {
        const cyclesCompleted = countdown.cycleCount - prevCycleCount.current;
        const newPerformedSteps: PerformedStep[] = [];

        for(let i=0; i < cyclesCompleted; i++) {
            const cycleNumber = prevCycleCount.current + i + 1;
            const exerciseStep: WorkoutStep = {
                id: `manual-exercise-${cycleNumber}`,
                name: 'Interval',
                type: 'exercise',
                isRepBased: false,
                duration: settings.countdownDuration,
                reps: 0,
            };
            newPerformedSteps.push({
                step: exerciseStep,
                status: StepStatus.Completed,
                durationMs: settings.countdownDuration * 1000,
            });

            if (settings.countdownRestDuration > 0) {
                const restStep: WorkoutStep = {
                    id: `manual-rest-${cycleNumber}`,
                    name: 'Rest',
                    type: 'rest',
                    isRepBased: false,
                    duration: settings.countdownRestDuration,
                    reps: 0,
                };
                newPerformedSteps.push({
                    step: restStep,
                    status: StepStatus.Completed,
                    durationMs: settings.countdownRestDuration * 1000,
                });
            }
        }
        setManualSessionLog(currentLog => [...currentLog, ...newPerformedSteps]);
    }
    prevCycleCount.current = countdown.cycleCount;
  }, [countdown.cycleCount, isWorkoutActive, settings.countdownDuration, settings.countdownRestDuration]);

  // Sync prevCycleCount on reset
  useEffect(() => {
      if (countdown.cycleCount === 0) {
          prevCycleCount.current = 0;
      }
  }, [countdown.cycleCount]);

  const isPastHalfway = settings.showCountdown && countdown.isRunning && countdown.timeLeft <= countdownDuration / 2 && countdown.timeLeft > 0;

  useEffect(() => {
    if (activeWorkout) {
        lastActiveWorkoutRef.current = activeWorkout;
    }
  }, [activeWorkout]);

  useEffect(() => {
    document.body.style.backgroundColor = settings.backgroundColor;
  }, [settings.backgroundColor]);

  // Handle the pre-workout countdown
  useEffect(() => {
    let timer: ReturnType<typeof setInterval> | undefined;
    if (isPreparingWorkout) {
        let count = settings.preWorkoutCountdownDuration;
        setPreWorkoutTimeLeft(count);

        timer = setInterval(() => {
            count -= 1;
            setPreWorkoutTimeLeft(count);

            if (count <= 0) {
                clearInterval(timer);
                setTimeout(() => {
                    commitStartWorkout();
                }, 1000);
            }
        }, 1000);

        return () => { if (timer) clearInterval(timer); };
    } else {
        setPreWorkoutTimeLeft(null);
    }
  }, [isPreparingWorkout, commitStartWorkout, settings.preWorkoutCountdownDuration]);


  const toggleFullScreen = useCallback(() => {
    logAction('TOGGLE_FULLSCREEN', { isFullscreen: !!document.fullscreenElement });
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().catch(err => {
            console.error(`Error attempting to enable full-screen mode: ${err.message} (${err.name})`);
            logAction('ERROR_FULLSCREEN_ENTER', { message: err.message, name: err.name });
        });
    } else {
        if (document.exitFullscreen) {
            document.exitFullscreen();
        }
    }
  }, [logAction]);

    // Swipe gesture detection
    const touchStartX = useRef<number>(0);
    const touchStartY = useRef<number>(0);
    const touchEndX = useRef<number>(0);
    const touchEndY = useRef<number>(0);

    const handleTouchStart = (e: React.TouchEvent<HTMLDivElement>) => {
      const target = e.target as HTMLElement;
      if (target.closest('button, input, a, [role="button"]')) {
        return;
      }
      touchStartX.current = e.targetTouches[0].clientX;
      touchStartY.current = e.targetTouches[0].clientY;
      touchEndX.current = 0;
      touchEndY.current = 0;
    };

    const handleTouchMove = (e: React.TouchEvent<HTMLDivElement>) => {
      touchEndX.current = e.targetTouches[0].clientX;
      touchEndY.current = e.targetTouches[0].clientY;
    };

    const handleTouchEnd = () => {
      if (!touchStartX.current || !touchEndX.current) return;

      const diffX = touchEndX.current - touchStartX.current;
      const diffY = touchEndY.current - touchStartY.current;
      const swipeThreshold = 50;
      const edgeThreshold = 50;

      if (Math.abs(diffX) > Math.abs(diffY) && Math.abs(diffX) > swipeThreshold) {
        if (isSettingsOpen || isWorkoutOpen) return;

        if (diffX > 0 && touchStartX.current < edgeThreshold) {
          logAction('SWIPE_OPEN_WORKOUT_MENU');
          setIsWorkoutOpen(true);
        }

        if (diffX < 0 && touchStartX.current > window.innerWidth - edgeThreshold) {
          logAction('SWIPE_OPEN_SETTINGS_MENU');
          setIsSettingsOpen(true);
        }
      }

      touchStartX.current = 0;
      touchStartY.current = 0;
      touchEndX.current = 0;
      touchEndY.current = 0;
    };

  // Keyboard and interaction shortcuts
  useEffect(() => {
    const handleUniversalStartStop = () => {
        if (isRepStep || isWorkoutActive) return;

        const isAnythingRunning = stopwatch.isRunning || countdown.isRunning || countdown.isResting;
        if (isAnythingRunning) {
          stopwatch.stop();
          countdown.stop();
        } else {
          stopwatch.start();
          countdown.start();
        }
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement) {
        return;
      }

      const key = event.key.toLowerCase();
      let newVolume: number;

      logAction('KEY_DOWN', { key: event.key, code: event.code });

      const toggleMute = () => {
        if (settings.isMuted) {
          updateSettings({
            isMuted: false,
            volume: settings.volume === 0 ? 0.5 : settings.volume,
          });
        } else {
          updateSettings({ isMuted: true });
        }
      };

      switch (key) {
        case 'm':
        case 'צ':
          toggleMute();
          break;
        case 'arrowup':
          event.preventDefault();
          newVolume = Math.min(1, (settings.isMuted ? 0 : settings.volume) + 0.05);
          updateSettings({ volume: newVolume, isMuted: false });
          if(settings.allSoundsEnabled && !settings.stealthModeEnabled) playNotificationSound(newVolume);
          break;
        case 'arrowdown':
          event.preventDefault();
          newVolume = Math.max(0, (settings.isMuted ? 0 : settings.volume) - 0.05);
          updateSettings({ volume: newVolume, isMuted: newVolume === 0 });
          // Fix: play volume notification sound even on down arrow if allowed
          if(settings.allSoundsEnabled && !settings.stealthModeEnabled) playNotificationSound(newVolume);
          break;
        case ' ':
        case 'k':
        case 'ל':
          event.preventDefault();
          handleUniversalStartStop();
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [settings, updateSettings, stopwatch, countdown, isRepStep, isWorkoutActive, logAction]);

  const workoutStepInfo = useMemo(() => {
    if (!activeWorkout) return undefined;
    return {
      current: activeWorkout.currentStepIndex + 1,
      total: activeWorkout.plan.steps.length
    };
  }, [activeWorkout]);

  return (
    <div 
      className="min-h-screen flex flex-col items-center justify-center p-4 transition-colors duration-500 overflow-hidden"
      style={{ backgroundColor: isRestStep ? settings.restBackgroundColor : (isPastHalfway ? settings.halfwayColor : settings.backgroundColor), color: isRestStep ? (settings.restBackgroundColor === '#ffffff' || settings.restBackgroundColor === 'white' ? 'black' : 'white') : 'white' }}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
    >
      <style>{`
        :root {
          --countdown-font-size: ${settings.countdownSize * 2}px;
          --stopwatch-font-size: ${settings.stopwatchSize / 2}px;
          --countdown-controls-scale: ${settings.countdownControlsSize / 100};
          --stopwatch-controls-scale: ${settings.stopwatchControlsSize / 100};
        }
        @media (min-width: 768px) {
          :root {
            --countdown-font-size: ${settings.countdownSize * 4}px;
            --stopwatch-font-size: ${settings.stopwatchSize}px;
          }
        }
        @keyframes pop {
          0% { transform: scale(0.8); opacity: 0; }
          50% { transform: scale(1.1); opacity: 1; }
          100% { transform: scale(1); opacity: 1; }
        }
        .animate-pop {
          animation: pop 1s ease-out forwards;
        }
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        .animate-fadeIn {
          animation: fadeIn 0.3s ease-out forwards;
        }
        @keyframes glow {
          0% { box-shadow: 0 0 5px rgba(59, 130, 246, 0.5); }
          50% { box-shadow: 0 0 20px rgba(59, 130, 246, 0.8); }
          100% { box-shadow: 0 0 5px rgba(59, 130, 246, 0.5); }
        }
        .animate-glow {
          animation: glow 2s infinite;
        }
      `}</style>

      {isPreparingWorkout && preWorkoutTimeLeft !== null && (
        <PreWorkoutCountdown 
            timeLeft={preWorkoutTimeLeft} 
            onDoubleClick={clearPreparingWorkout} 
        />
      )}

      {importNotification && (
          <ImportNotification 
              message={importNotification.message}
              planName={importNotification.planName}
              type={importNotification.type}
              onClose={clearImportNotification}
          />
      )}

      {showGuestMergeModal && (
          <GuestDataMergeModal 
              guestPlans={guestPlansToMerge}
              guestHistoryCount={guestHistoryToMerge.length}
              onMerge={handleMergeGuestData}
              onDiscard={handleDiscardGuestData}
          />
      )}

      {isLoggingModalOpen && (
          <LogSessionModal 
              onSave={(name) => {
                  logManualSession(name, stopwatch.time, manualSessionLog);
                  setIsLoggingModalOpen(false);
                  setManualSessionLog([]);
                  stopwatch.reset();
              }}
              onClose={() => setIsLoggingModalOpen(false)}
          />
      )}

      {showCrashNotification && (
          <CrashNotification 
              onCopy={handleCopyCrashReport}
              onDismiss={handleDismissCrashReport}
          />
      )}

      <WorkoutMenu isOpen={isWorkoutOpen} setIsOpen={setIsWorkoutOpen} />
      <SettingsMenu isOpen={isSettingsOpen} setIsOpen={setIsSettingsOpen} />

      <div className="flex-1 flex flex-col items-center justify-center w-full max-w-4xl">
        <div className="mb-4 text-center">
            {isWorkoutActive && (
                <div className="mb-2 animate-fadeIn">
                    <h2 className="text-2xl md:text-3xl font-bold opacity-90">
                        {isRestStep ? (settings.showRestTitleOnDefaultCountdown ? 'Rest' : getStepDisplayName(currentStep)) : getStepDisplayName(currentStep)}
                    </h2>
                    {settings.showNextExercise && nextUpcomingStep && (
                         <p className="text-sm md:text-base text-gray-400 mt-1">
                            Next: {getStepDisplayName(nextUpcomingStep)}
                        </p>
                    )}
                </div>
            )}
        </div>

        <div className="relative w-full flex flex-col items-center">
          {isRepStep ? (
            <RepDisplay reps={currentStep.reps} onComplete={() => nextStepWithTime(StepStatus.Completed)} />
          ) : (
            <>
              {settings.showCountdown && (
                <div className="relative">
                  <CountdownDisplay timeLeft={countdown.timeLeft} />
                  {settings.showCountdownControls && (
                    <CountdownControls 
                        isRunning={countdown.isRunning}
                        start={countdown.start}
                        stop={countdown.stop}
                        reset={countdown.reset}
                    />
                  )}
                </div>
              )}
            </>
          )}
        </div>

        {settings.showTimer && (
          <div className={`mt-12 flex flex-col items-center transition-opacity duration-300 ${isRepStep ? 'opacity-50' : 'opacity-100'}`}>
            <TimerDisplay time={stopwatch.time} />
            <Controls 
              isRunning={stopwatch.isRunning}
              start={stopwatch.start}
              stop={stopwatch.stop}
              reset={stopwatch.reset}
              cycleCount={settings.showCycleCounter ? countdown.cycleCount : null}
              resetCycleCount={countdown.resetCycleCount}
              showTimer={settings.showTimer}
              showStopwatchControls={settings.showStopwatchControls}
              isWorkoutActive={isWorkoutActive}
              nextStep={() => nextStepWithTime(StepStatus.Skipped)}
              previousStep={previousStepWithTime}
              workoutStepInfo={workoutStepInfo}
              showLogSessionButton={settings.showLogSessionButton && !isWorkoutActive && stopwatch.time > 0}
              onLogSession={() => setIsLoggingModalOpen(true)}
            />
          </div>
        )}
      </div>

      <div className="absolute bottom-4 right-4 menu-container group">
        <button 
          onClick={toggleFullScreen}
          className="w-10 h-10 flex items-center justify-center rounded-full bg-gray-500/10 text-gray-500 hover:bg-gray-500/20 transition-all opacity-0 group-hover:opacity-100"
          title="Toggle Fullscreen"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
          </svg>
        </button>
      </div>
    </div>
  );
};

