// (Other components remain same, focus on AiPlannerModal)

const AiPlannerModal: React.FC<{ onClose: () => void; }> = ({ onClose }) => {
    type ChatMessage = { role: 'user' | 'model'; parts: { text: string; isPlanLink?: boolean; planName?: string }[] };
    const { importPlan } = useWorkout();
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    useLayoutEffect(() => {
        const textarea = textareaRef.current;
        if (textarea) {
            textarea.style.height = 'auto';
            const maxHeight = 150;
            textarea.style.height = `${Math.min(textarea.scrollHeight, maxHeight)}px`;
            textarea.style.overflowY = textarea.scrollHeight > maxHeight ? 'auto' : 'hidden';
        }
    }, [input]);

    const handleSend = async () => {
        if (!input.trim() || isLoading) return;
        const userMsg: ChatMessage = { role: 'user', parts: [{ text: input.trim() }] };
        setMessages(prev => [...prev, userMsg]);
        setInput('');
        setIsLoading(true);

        try {
            const responseText = await generateWorkoutPlan(messages, input.trim());
            const jsonRegex = /```json\s*([\s\S]*?)\s*```/;
            const match = responseText.match(jsonRegex);
            const conversationalText = responseText.replace(jsonRegex, '').trim();

            const modelParts: any[] = [];
            if (conversationalText) modelParts.push({ text: conversationalText });
            if (match && match[1]) {
                try {
                    const plan = JSON.parse(match[1]);
                    importPlan(plan, 'ai');
                    modelParts.push({ text: '', isPlanLink: true, planName: plan.name });
                } catch (e) { console.error(e); }
            }
            setMessages(prev => [...prev, { role: 'model', parts: modelParts }]);
        } catch (e) {
            setMessages(prev => [...prev, { role: 'model', parts: [{ text: 'סליחה, קרתה שגיאה.' }] }]);
        } finally { setIsLoading(false); }
    };

    return (
        <div className="fixed inset-0 bg-gray-900/95 z-[100] flex flex-col p-4">
            <div className="flex justify-between items-center mb-4 text-white">
                <h2 className="text-xl font-bold">✨ AI Workout Planner</h2>
                <button onClick={onClose} className="p-2 bg-gray-700 rounded-full">X</button>
            </div>
            <div className="flex-grow overflow-y-auto mb-4 space-y-4">
                {messages.map((m, i) => (
                    <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`p-3 rounded-lg max-w-[80%] ${m.role === 'user' ? 'bg-blue-600' : 'bg-gray-800'}`}>
                            {m.parts.map((p, pi) => p.isPlanLink ? (
                                <p key={pi} className="text-green-400">הוספתי את תוכנית {p.planName}!</p>
                            ) : (
                                <p key={pi} className="whitespace-pre-wrap text-white" dir="auto">{p.text}</p>
                            ))}
                        </div>
                    </div>
                ))}
                <div ref={messagesEndRef} />
            </div>
            <div className="flex gap-2 items-end">
                <textarea
                    ref={textareaRef}
                    value={input}
                    onChange={e => setInput(e.target.value)}
                    onKeyDown={e => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSend();
                        }
                    }}
                    placeholder="תאר את האימון שתרצה..."
                    className="flex-grow bg-gray-800 text-white p-3 rounded-lg focus:outline-none focus:ring-2 ring-blue-500 resize-none min-h-[48px]"
                    dir="rtl"
                />
                <button onClick={handleSend} disabled={isLoading} className="p-3 bg-blue-600 rounded-lg text-white font-bold">שלח</button>
            </div>
        </div>
    );
};

