        if ('wakeLock' in navigator && settings.keepScreenOnEnabled) {
            try {
                wakeLock = await (navigator as any).wakeLock.request('screen');
            } catch (err) {
                console.error("Wake Lock error:", err);
            }
        }
    };

    requestWakeLock();

    const handleVisibilityChange = () => {
        if (wakeLock !== null && document.visibilityState === 'visible') {
            requestWakeLock();
        }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
        if (wakeLock) wakeLock.release();
        document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [settings.keepScreenOnEnabled]);

  const countdown = useCountdown(
    activeWorkout && currentStep && !currentStep.isRepBased ? currentStep.duration : settings.countdownDuration,
    settings.countdownRestDuration,
    settings,
    activeWorkout ? () => nextStep(Date.now(), 'completed' as any) : undefined
  );

  useEffect(() => {
    const handleFirstInteraction = () => {
      resumeAudioContext();
      window.removeEventListener('click', handleFirstInteraction);
      window.removeEventListener('touchstart', handleFirstInteraction);
    };
    window.addEventListener('click', handleFirstInteraction);
    window.addEventListener('touchstart', handleFirstInteraction);
  }, []);

  return (
    <div 
      className="min-h-screen flex flex-col items-center justify-center p-4 transition-colors duration-500 overflow-hidden"
      style={{ backgroundColor: settings.backgroundColor, color: 'white' }}
    >
      <style>{`
        :root {
          --countdown-font-size: ${settings.countdownSize * 2}px;
          --stopwatch-font-size: ${settings.stopwatchSize / 2}px;
        }
        @media (min-width: 768px) {
          :root {
            --countdown-font-size: ${settings.countdownSize * 4}px;
            --stopwatch-font-size: ${settings.stopwatchSize}px;
          }
        }
      `}</style>

      <div className="absolute top-4 left-4 flex gap-4">
        <button onClick={() => setIsWorkoutOpen(true)} className="p-4 bg-gray-700/50 rounded-full hover:bg-gray-700 transition-colors">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h7" /></svg>
        </button>
      </div>

      <div className="absolute top-4 right-4">
        <button onClick={() => setIsSettingsOpen(true)} className="p-4 bg-gray-700/50 rounded-full hover:bg-gray-700 transition-colors">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
        </button>
      </div>

      <WorkoutMenu isOpen={isWorkoutOpen} setIsOpen={setIsWorkoutOpen} />
      <SettingsMenu isOpen={isSettingsOpen} setIsOpen={setIsSettingsOpen} />

      <div className="flex-1 flex flex-col items-center justify-center w-full max-w-4xl">
        {activeWorkout && currentStep && (
            <div className="mb-8 text-center animate-fadeIn">
                <h2 className="text-4xl font-bold">{getStepDisplayName(currentStep)}</h2>
            </div>
        )}

        {activeWorkout && currentStep?.isRepBased ? (
            <RepDisplay reps={currentStep.reps} onComplete={() => nextStep(Date.now(), 'completed' as any)} />
        ) : (
            <div className="flex flex-col items-center">
                <CountdownDisplay timeLeft={countdown.timeLeft} />
                <CountdownControls 
                    isRunning={countdown.isRunning} 
                    start={countdown.start} 
                    stop={countdown.stop} 
                    reset={countdown.reset} 
                />
            </div>
        )}

        <div className="mt-16 flex flex-col items-center">
            <TimerDisplay time={stopwatch.time} />
            <Controls 
                isRunning={stopwatch.isRunning} 
                start={stopwatch.start} 
                stop={stopwatch.stop} 
                reset={stopwatch.reset} 
                cycleCount={settings.showCycleCounter ? countdown.cycleCount : null}
                resetCycleCount={countdown.resetCycleCount}
                showTimer={true}
                showStopwatchControls={true}
                isWorkoutActive={!!activeWorkout}
                nextStep={() => nextStep(Date.now(), 'skipped' as any)}
                previousStep={() => previousStep(Date.now())}
            />
        </div>
      </div>
    </div>
  );
};

