}

const WorkoutContext = createContext<WorkoutContextType | undefined>(undefined);

export const WorkoutProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { settings } = useSettings();
  const { user, authStatus } = useAuth();
  const { logAction } = useLogger();

  // Initialize from local storage to prevent blank states on refresh
  const [plans, setPlans] = useState<WorkoutPlan[]>(() => 
    getLocalPlans().map(migratePlanToV2).filter((p): p is WorkoutPlan => !!p)
  );
  const [workoutHistory, setWorkoutHistory] = useState<WorkoutLogEntry[]>(() => getLocalHistory());

  const [activeWorkout, setActiveWorkout] = useState<ActiveWorkout | null>(null);
  const [isWorkoutPaused, setIsWorkoutPaused] = useState(false);
  const [isCountdownPaused, setIsCountdownPaused] = useState(false);
  const [recentlyImportedPlanId, setRecentlyImportedPlanId] = useState<string | null>(null);
  const [plansToStart, setPlansToStart] = useState<string[]>([]);
  const [importNotification, setImportNotification] = useState<ImportNotificationData | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);

  const [showGuestMergeModal, setShowGuestMergeModal] = useState(false);
  const [guestPlansToMerge, setGuestPlansToMerge] = useState<WorkoutPlan[]>([]);
  const [guestHistoryToMerge, setGuestHistoryToMerge] = useState<WorkoutLogEntry[]>([]);

  const isPreparingWorkout = plansToStart.length > 0;

  const clearImportNotification = useCallback(() => setImportNotification(null), []);

  const handleFirestoreError = useCallback((error: FirestoreError, context: string) => {
      console.error(`Firestore error in ${context}:`, error);
      logAction(`ERROR_FIRESTORE_${context}`, { message: error.message, code: error.code });
      if (error.code === 'permission-denied') {
          setImportNotification({
              message: 'שגיאת הרשאות',
              planName: 'נא לעדכן חוקי אבטחה ב-Firebase Console',
              type: 'warning',
          });
      }
      setIsSyncing(false);
  }, [logAction]);

  useEffect(() => {
    let plansUnsubscribe: Unsubscribe | undefined;
    let historyUnsubscribe: Unsubscribe | undefined;

    if (authStatus === 'authenticated' && user) {
        setIsSyncing(true);
        const plansCollection = collection(db, 'users', user.uid, 'plans');
        plansUnsubscribe = onSnapshot(query(plansCollection, orderBy('order', 'asc')), (snapshot) => {
            const remotePlans = snapshot.docs.map(doc => migratePlanToV2(doc.data())).filter((p): p is WorkoutPlan => !!p);
            // Optimization: Only update state if remote is actually different to avoid unnecessary rerenders
            setPlans(remotePlans);
            saveLocalPlans(remotePlans); // Cache for next refresh
            setIsSyncing(false);
        }, (error) => handleFirestoreError(error, 'PLANS_LISTENER'));

        const historyCollection = collection(db, 'users', user.uid, 'history');
        historyUnsubscribe = onSnapshot(query(historyCollection, orderBy('date', 'desc')), (snapshot) => {
            const remoteHistory = snapshot.docs.map(doc => doc.data() as WorkoutLogEntry);
            setWorkoutHistory(remoteHistory);
            saveLocalHistory(remoteHistory); // Cache for next refresh
        }, (error) => handleFirestoreError(error, 'HISTORY_LISTENER'));

    } else if (authStatus === 'unauthenticated') {
        // In guest mode, already initialized from local storage
        setIsSyncing(false);
    }

    return () => {
        if (plansUnsubscribe) plansUnsubscribe();
        if (historyUnsubscribe) historyUnsubscribe();
    };
  }, [user, authStatus, logAction, handleFirestoreError]);

  const savePlan = useCallback(async (planToSave: WorkoutPlan) => {
      logAction('PLAN_SAVE_ATTEMPT', { planId: planToSave.id });
      const migratedPlan = migratePlanToV2(planToSave);
      if (!migratedPlan) return;

      // Always save locally immediately as a cache/backup
      setPlans(prevPlans => {
          const isNewPlan = !prevPlans.some(p => p.id === migratedPlan.id);
          let newPlans;
          if (isNewPlan) {
              const maxOrder = prevPlans.reduce((max, p) => Math.max(max, p.order ?? -1), -1);
              migratedPlan.order = maxOrder + 1;
              newPlans = [...prevPlans, migratedPlan];
          } else {
              newPlans = prevPlans.map(p => p.id === migratedPlan.id ? migratedPlan : p);
          }
          saveLocalPlans(newPlans);
          return newPlans;
      });

      if (user) {
          try {
              const planRef = doc(db, 'users', user.uid, 'plans', migratedPlan.id);
              await setDoc(planRef, migratedPlan, { merge: true });
          } catch (error) {
              handleFirestoreError(error as FirestoreError, 'PLAN_SAVE');
          }
      }
  }, [user, logAction, handleFirestoreError]);

  const importPlan = useCallback((planToImport: WorkoutPlan, source: string = 'file') => {
    const migratedPlan = migratePlanToV2(planToImport);
    if (!migratedPlan) return;

    const newPlanId = `${Date.now()}_imported_${source}`;
    const newPlan: WorkoutPlan = {
      ...migratedPlan,
      id: newPlanId,
      steps: migratedPlan.steps.map((step, index) => ({
        ...step,
        id: `${Date.now()}_imported_step_${index}`
      }))
    };

    if (source === 'ai') {
        newPlan.steps = processAndFormatAiSteps(newPlan.steps);
        newPlan.steps = newPlan.steps.map(step => {
            if (step.type === 'exercise' && !step.isRepBased && (!step.duration || step.duration <= 0)) {
                return { ...step, isRepBased: true, reps: 10, duration: 0 };
            }
            return step;
        });
    }

    savePlan(newPlan);
    setImportNotification({ message: 'תוכנית אימונים יובאה בהצלחה!', planName: newPlan.name, type: 'success' });
    setRecentlyImportedPlanId(newPlanId);
    setTimeout(() => setRecentlyImportedPlanId(null), 2500);
  }, [savePlan]);

  const value = {
    plans,
    activeWorkout,
    currentStep: activeWorkout ? activeWorkout.plan.steps[activeWorkout.currentStepIndex] : null,
    nextUpcomingStep: useMemo(() => {
        if (!activeWorkout) return null;
        return activeWorkout.plan.steps[activeWorkout.currentStepIndex + 1] || null;
    }, [activeWorkout]),
    isWorkoutPaused,
    isCountdownPaused,
    recentlyImportedPlanId,
    workoutHistory,
    isPreparingWorkout,
    isSyncing,
    importNotification,
    showGuestMergeModal,
    guestPlansToMerge,
    guestHistoryToMerge,
    handleMergeGuestData: () => {}, // To be implemented or handled elsewhere
    handleDiscardGuestData: () => {},
    clearImportNotification,
    savePlan,
    importPlan,
    deletePlan: async (planId: string) => {
        if (user) {
            try {
                await deleteDoc(doc(db, 'users', user.uid, 'plans', planId));
            } catch (e) { handleFirestoreError(e as FirestoreError, 'DELETE_PLAN'); }
        } else {
            const newPlans = plans.filter(p => p.id !== planId);
            setPlans(newPlans);
            saveLocalPlans(newPlans);
        }
    },
    reorderPlans: (reordered: WorkoutPlan[]) => {
        setPlans(reordered);
        saveLocalPlans(reordered);
        // Sync reorder to Firestore if needed
    },
    startWorkout: (planIds: string[]) => setPlansToStart(planIds),
    commitStartWorkout: () => {
        const plansToRun = plansToStart.map(id => plans.find(p => p.id === id)).filter(Boolean) as WorkoutPlan[];
        if (plansToRun.length === 0) return;
        const allSteps = plansToRun.flatMap(p => p.steps);
        setActiveWorkout({
            plan: { id: 'meta', name: plansToRun.map(p => p.name).join(' & '), steps: allSteps },
            currentStepIndex: 0,
            sourcePlanIds: plansToStart,
            sessionLog: [],
            stepStartTime: Date.now(),
        });
        setPlansToStart([]);
    },
    clearPreparingWorkout: () => setPlansToStart([]),
    stopWorkout: () => setActiveWorkout(null),
    nextStep: () => {
        setActiveWorkout(prev => {
            if (!prev || prev.currentStepIndex + 1 >= prev.plan.steps.length) return null;
            return { ...prev, currentStepIndex: prev.currentStepIndex + 1, stepStartTime: Date.now() };
        });
    },
    previousStep: () => {
        setActiveWorkout(prev => {
            if (!prev || prev.currentStepIndex === 0) return prev;
            return { ...prev, currentStepIndex: prev.currentStepIndex - 1, stepStartTime: Date.now() };
        });
    },
    pauseWorkout: () => setIsWorkoutPaused(true),
    resumeWorkout: () => setIsWorkoutPaused(false),
    restartWorkout: () => {},
    pauseStepCountdown: () => setIsCountdownPaused(true),
    resumeStepCountdown: () => setIsCountdownPaused(false),
    restartCurrentStep: () => {
        setActiveWorkout(prev => prev ? { ...prev, stepRestartKey: (prev.stepRestartKey || 0) + 1, stepStartTime: Date.now() } : null);
    },
    clearWorkoutHistory: () => {
        setWorkoutHistory([]);
        saveLocalHistory([]);
    },
    forceSync: () => {
        // Logic to force a fresh pull from Firebase
    },
    logManualSession: (name: string, duration: number, steps: PerformedStep[]) => {
        const newEntry: WorkoutLogEntry = { id: Date.now().toString(), date: new Date().toISOString(), planName: name, durationSeconds: Math.floor(duration/1000), steps: [], performedSteps: steps };
        const updatedHistory = [newEntry, ...workoutHistory];
        setWorkoutHistory(updatedHistory);
        saveLocalHistory(updatedHistory);
    },
  };

  return <WorkoutContext.Provider value={value}>{children}</WorkoutContext.Provider>;
};

export const useWorkout = () => {
  const context = useContext(WorkoutContext);
  if (!context) throw new Error('useWorkout must be used within a WorkoutProvider');
  return context;
};

