        {activeWorkout && currentStep && (
            <div className="mb-8 text-center animate-fadeIn">
                <h2 className="text-4xl font-bold">{getStepDisplayName(currentStep)}</h2>
            </div>
        )}

        <div className="w-full flex flex-col items-center">
            {activeWorkout && currentStep?.isRepBased ? (
                <RepDisplay reps={currentStep.reps} onComplete={() => nextStep(Date.now(), 'completed' as any)} />
            ) : (
                <>
                    <CountdownDisplay timeLeft={countdown.timeLeft} />
                    <CountdownControls 
                        isRunning={countdown.isRunning} 
                        start={countdown.start} 
                        stop={countdown.stop} 
                        reset={countdown.reset} 
                    />
                </>
            )}
        </div>

        <div className="mt-16 flex flex-col items-center">
            <TimerDisplay time={stopwatch.time} />
            <Controls 
                isRunning={stopwatch.isRunning} 
                start={stopwatch.start} 
                stop={stopwatch.stop} 
                reset={stopwatch.reset} 
                cycleCount={settings.showCycleCounter ? countdown.cycleCount : null}
                resetCycleCount={countdown.resetCycleCount}
                showTimer={true}
                showStopwatchControls={true}
                isWorkoutActive={!!activeWorkout}
                nextStep={() => nextStep(Date.now(), 'skipped' as any)}
                previousStep={() => previousStep(Date.now())}
            />
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
    return (
        <LoggingProvider>
            <AuthProvider>
                <SettingsProvider>
                    <WorkoutProvider>
                        <ErrorBoundary>
                            <AppContent />
                        </ErrorBoundary>
                    </WorkoutProvider>
                </SettingsProvider>
            </AuthProvider>
        </LoggingProvider>
    );
};

export default App;

import React, { useState, useEffect, useRef, useMemo, useLayoutEffect } from 'react';
import { useWorkout } from '../contexts/WorkoutContext';
import { WorkoutPlan, WorkoutStep } from '../types';
import { useSettings } from '../contexts/SettingsContext';
import { generateWorkoutPlan } from '../services/geminiService';
import { useAuth } from '../contexts/AuthContext';
import { getStepDisplayName } from '../utils/workout';

const AiPlannerModal: React.FC<{ onClose: () => void; }> = ({ onClose }) => {
    type ChatMessage = { role: 'user' | 'model'; parts: { text: string; isPlanLink?: boolean; planName?: string }[] };
    const { importPlan } = useWorkout();
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    useLayoutEffect(() => {
        const textarea = textareaRef.current;
        if (textarea) {
            textarea.style.height = 'auto';
            const maxHeight = 150;
            textarea.style.height = `${Math.min(textarea.scrollHeight, maxHeight)}px`;
            textarea.style.overflowY = textarea.scrollHeight > maxHeight ? 'auto' : 'hidden';
        }
    }, [input]);

    const handleSend = async () => {
        const trimmedInput = input.trim();
        if (!trimmedInput || isLoading) return;

        const userMsg: ChatMessage = { role: 'user', parts: [{ text: trimmedInput }] };
        setMessages(prev => [...prev, userMsg]);
        setInput('');
        setIsLoading(true);

        try {
            const responseText = await generateWorkoutPlan(messages, trimmedInput);
            const jsonRegex = /```json\s*([\s\S]*?)\s*```/;
            const match = responseText.match(jsonRegex);
            const conversationalText = responseText.replace(jsonRegex, '').trim();

            const modelParts: any[] = [];
            if (conversationalText) modelParts.push({ text: conversationalText });
            if (match && match[1]) {
                try {
                    const plan = JSON.parse(match[1]);
                    importPlan(plan, 'ai');
                    modelParts.push({ text: '', isPlanLink: true, planName: plan.name });
                } catch (e) { console.error("AI JSON Parse Error", e); }
            }
            setMessages(prev => [...prev, { role: 'model', parts: modelParts }]);
        } catch (e) {
            setMessages(prev => [...prev, { role: 'model', parts: [{ text: 'סליחה, קרתה שגיאה במענה. נסה שוב.' }] }]);
        } finally { setIsLoading(false); }
    };

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    return (
        <div className="fixed inset-0 bg-gray-900/95 z-[100] flex flex-col p-4">
            <div className="flex justify-between items-center mb-4 text-white">
                <h2 className="text-xl font-bold flex items-center gap-2">✨ AI Workout Planner</h2>
                <button onClick={onClose} className="p-2 bg-gray-700 hover:bg-gray-600 rounded-full transition-colors">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
            </div>
            <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2">
                {messages.length === 0 && (
                  <p className="text-gray-400 text-center mt-10">תאר את האימון שתרצה לבצע, וה-AI יבנה לך תוכנית מותאמת אישית.</p>
                )}
                {messages.map((m, i) => (
                    <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`p-3 rounded-lg max-w-[85%] ${m.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-800 text-gray-200 shadow-lg'}`}>
                            {m.parts.map((p, pi) => p.isPlanLink ? (
                                <div key={pi} className="mt-2 p-2 bg-green-900/30 border border-green-500/50 rounded flex items-center justify-between gap-3">
                                    <span className="text-sm">הוספתי את: <b>{p.planName}</b></span>
                                    <button onClick={onClose} className="text-xs bg-green-600 px-2 py-1 rounded text-white font-bold">צפה</button>
                                </div>
                            ) : (
                                <p key={pi} className="whitespace-pre-wrap leading-relaxed text-sm md:text-base" dir="auto">{p.text}</p>
                            ))}
                        </div>
                    </div>
                ))}
                {isLoading && (
                  <div className="flex justify-start">
                    <div className="bg-gray-800 p-3 rounded-lg animate-pulse text-gray-400 text-sm">ה-AI חושב...</div>
                  </div>
                )}
                <div ref={messagesEndRef} />
            </div>
            <div className="flex gap-2 items-end bg-gray-800 p-2 rounded-xl border border-gray-700">
                <textarea
                    ref={textareaRef}
                    value={input}
                    onChange={e => setInput(e.target.value)}
                    onKeyDown={e => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSend();
                        }
                    }}
                    placeholder="תאר את האימון שתרצה..."
                    className="flex-grow bg-transparent text-white p-2 focus:outline-none resize-none min-h-[40px] text-sm md:text-base"
                    dir="rtl"
                />
                <button 
                  onClick={handleSend} 
                  disabled={isLoading || !input.trim()} 
                  className="p-2 bg-blue-600 hover:bg-blue-500 disabled:bg-gray-700 rounded-lg text-white font-bold transition-colors"
                >
                    <svg className="w-6 h-6 rotate-180" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                </button>
            </div>
        </div>
    );
};

export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void; }> = ({ isOpen, setIsOpen }) => {
    const [view, setView] = useState<'list' | 'editor' | 'ai'>('list');
    const { plans, startWorkout } = useWorkout();

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[70] flex">
            <div className="fixed inset-0 bg-black/70 backdrop-blur-sm" onClick={() => setIsOpen(false)}></div>
            <div className="relative w-full max-w-sm bg-gray-900/90 h-full p-6 shadow-2xl animate-fadeIn overflow-y-auto border-r border-gray-800">
                {view === 'list' && (
                    <div className="space-y-6">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-2xl font-bold text-white">אימונים</h2>
                            <div className="flex gap-2">
                              <button onClick={() => setView('ai')} className="p-2 bg-purple-600 hover:bg-purple-500 rounded-lg text-xs text-white font-bold shadow-lg transition-all">✨ AI</button>
                              <button onClick={() => setIsOpen(false)} className="p-2 bg-gray-800 text-gray-400 rounded-lg"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
                            </div>
                        </div>

                        {plans.length === 0 ? (
                          <div className="text-center py-20 text-gray-500">
                            <p>אין תוכניות שמורות.</p>
                            <button onClick={() => setView('ai')} className="mt-4 text-blue-400 underline font-semibold">צור אחת עם AI</button>
                          </div>
                        ) : (
                          <div className="space-y-3">
                            {plans.map(p => (
                                <div key={p.id} className="bg-gray-800/80 p-4 rounded-xl border border-gray-700 flex justify-between items-center hover:bg-gray-800 transition-colors group">
                                    <div className="flex flex-col">
                                      <span className="text-white font-bold">{p.name}</span>
                                      <span className="text-xs text-gray-400">{p.steps.length} שלבים</span>
                                    </div>
                                    <button 
                                      onClick={() => {
                                        startWorkout([p.id]);
                                        setIsOpen(false);
                                      }} 
                                      className="px-4 py-2 bg-green-600 hover:bg-green-500 text-white rounded-lg font-bold transition-colors shadow-sm"
                                    >
                                      התחל
                                    </button>
                                </div>
                            ))}
                          </div>
                        )}
                    </div>
                )}
                {view === 'ai' && <AiPlannerModal onClose={() => setView('list')} />}
            </div>
        </div>
    );
};
